    // Who We Are page
    wwa_badge: 'Our Story',
    wwa_hero_title1: 'Built by people who were',
    wwa_hero_title2: 'once lost too',
    wwa_hero_sub: 'GrowVia was born from a simple frustration: talented, ambitious people were making career decisions in the dark. We decided to change that.',
    wwa_mission_label: 'Our Mission',
    wwa_mission_title: 'Connect generations and unlock potential',
    wwa_mission_p1: 'Too many students and young professionals face the same challenge: they have ambition, but lack direction.',
    wwa_mission_p2: "At the same time, there are thousands of experienced professionals who want to give back, share their knowledge, and make a real difference in someone else's career.",
    wwa_mission_p3: 'GrowVia bridges that gap. We create the conditions for genuine, structured, and impactful mentoring relationships.',
    wwa_stat_founded: 'Year Founded',
    wwa_stat_hq: 'Headquarters',
    wwa_stat_langs: 'Languages Supported',
    wwa_stat_vision: 'Vision',
