    wwa_vision_title: 'Become the global reference for quality mentoring',
    wwa_vision_sub: 'We are building more than a platform. We are creating a movement where every ambitious person has access to the guidance they need to reach their full potential.',
    wwa_vision_quote: '"GrowVia is not just mentoring. It is bringing clarity to your future."',
    wwa_founders_title: 'Meet the Founders',
    wwa_founders_sub: 'Two people on a mission to change how the world approaches career guidance.',
    wwa_founder1_bio: 'Luna experienced firsthand the confusion of choosing a career path after graduating. Unable to find mentors who truly understood her journey, she decided to build the platform she wished had existed.',
    wwa_founder2_bio: 'Yasmine brings a deep passion for human-centered design and community building. Having worked across multiple countries and industries, she understands the complexities of navigating a global job market.',
    wwa_values_title: 'What we believe in',
    wwa_values_sub: 'The principles that guide every decision we make at GrowVia.',
    wwa_value1_title: 'Human First',
    wwa_value1_desc: 'Every interaction on GrowVia is built around real human connection. We believe that the most powerful guidance comes from people who truly care.',
    wwa_value2_title: 'Clarity Over Noise',
