    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Frequently asked',
    faq_title2: 'questions',
    faq_sub: 'Everything you need to know about GrowVia. Cannot find your answer? Contact us directly.',
    faq_cat1: 'Getting Started',
    faq_cat2: 'Sessions & Booking',
    faq_cat3: 'Pricing & Payments',
    faq_cat4: 'Cancellation Policy',
    faq_cat5: 'Mentors',
    faq_cat6: 'For Schools',
    faq_cat1_q1: 'How do I get started on GrowVia?',
    faq_cat1_a1: 'Sign up, complete your profile, and book a Discovery Session for 9.99€. This 15–20 minute intro session lets you meet a mentor and try our AI Smart Matching feature once. No long-term commitment required.',
    faq_cat1_q2: 'Do I need an account to browse mentors?',
    faq_cat1_a2: 'You need to create a profile to access our full mentor directory and use AI matching. Creating a profile is free and takes about 5 minutes.',
    faq_cat1_q3: 'How do I become a mentee?',
    faq_cat1_a3: 'Simply register on GrowVia, complete your profile with your goals and background, and you can immediately start browsing mentors and book your free first session.',
    faq_cat2_q1: 'How do sessions work?',
    faq_cat2_a1: 'Sessions take place via Google Meet, which is integrated directly into the GrowVia platform. Once you book a session, a unique meeting link is automatically generated and shared with both you and your mentor via email. You just click the link to join.',
    faq_cat2_q2: 'How long are the sessions?',
    faq_cat2_a2: "Sessions are available in 30 or 60 minute formats, depending on the mentor's offerings and your preference.",
    faq_cat2_q3: 'Can I see my upcoming and past sessions?',
    faq_cat2_a3: 'Yes. Your personal calendar and session history are available in your dashboard. You can see upcoming sessions, past sessions, and their status (upcoming, completed, or cancelled).',
    faq_cat3_q1: 'How does payment work?',
    faq_cat3_a1: 'After choosing a mentor and selecting a time, you are guided through a secure checkout powered by Stripe. The Discovery Session costs 9.99€ (one-time). Monthly plans renew monthly and can be cancelled anytime.',
    faq_cat3_q2: 'Is payment secure?',
    faq_cat3_a2: 'Absolutely. All payments are processed through Stripe, which uses bank-grade TLS encryption. GrowVia never stores your card information on our servers. Your financial data is always protected.',
    faq_cat3_q3: 'What is included in the subscription plans?',
    faq_cat3_a3: 'Basic (19.99€/month) includes 2 sessions per month and 1 AI Smart Matching use. Premium (39.99€/month) includes 4 sessions per month, unlimited AI Smart Matching, priority booking, and personalized recommendations. Both plans can be cancelled anytime.',
    faq_cat3_q4: 'Are there any hidden fees?',
    faq_cat3_a4: 'No. The price you see is the price you pay. All prices include applicable VAT. There are no setup fees, cancellation fees, or hidden charges.',
    faq_cat4_q1: 'Can I cancel a booked session?',
    faq_cat4_a1: 'Yes. You can cancel a session at any time, but you must do so at least 1 hour before the scheduled start time. Late cancellations (within 1 hour of the session) are noted on your account.',
    faq_cat4_q2: 'Will I get a refund if I cancel?',
    faq_cat4_a2: 'No. Our cancellation policy does not include refunds, regardless of the reason for cancellation. If you cancel more than 1 hour in advance, your session credit may be returned depending on your plan.',
    faq_cat5_q1: 'How are mentors selected?',
    faq_cat5_a1: 'Every mentor on GrowVia goes through a manual approval process. They submit an application, and our team reviews their background, experience, and motivations before approving them. Only verified mentors appear on the platform.',
    faq_cat5_q2: 'Can I save mentors I like?',
    faq_cat5_a2: 'Yes. You can add mentors to your favorites by clicking the heart icon on their profile. Your saved mentors are accessible from your dashboard under Saved Mentors, and you can book directly from there.',
    faq_cat5_q3: 'What if I am not satisfied with my mentor match?',
    faq_cat5_a3: 'If the AI match does not feel right, you can browse our full mentor directory and choose a different mentor. Subscription users get unlimited AI matching attempts.',
    faq_cat6_q1: 'How can my school use GrowVia?',
    faq_cat6_a1: 'Schools can create an institutional account and invite students via a dedicated link. Students who sign up using their school email are automatically linked to the school account. The school admin can then track sessions, participation, and overall activity.',
    faq_cat6_q2: 'How do students get access through their school?',
    faq_cat6_a2: "Your school will send an invitation link to students. Students sign up using their school email address and are automatically connected to your institution's dashboard.",
    faq_still: 'Still have questions?',
    faq_still_sub: 'Our team is happy to help. Reach out and we will get back to you quickly.',
    faq_still_cta: 'Contact Us',

