    faq_cat6: 'Pour les Écoles',
    faq_cat1_q1: 'Comment commencer sur GrowVia ?',
    faq_cat1_a1: "Inscrivez-vous, complétez votre profil et réservez une Session Découverte pour 9,99€. Cette session d'introduction de 15–20 minutes vous permet de rencontrer un mentor et d'essayer notre Matching IA une fois. Aucun engagement à long terme requis.",
    faq_cat1_q2: "Ai-je besoin d'un compte pour voir les mentors ?",
    faq_cat1_a2: "Vous devez créer un profil pour accéder à notre annuaire complet de mentors et utiliser le matching IA. Créer un profil est gratuit et prend environ 5 minutes.",
    faq_cat1_q3: 'Comment devenir mentoré ?',
    faq_cat1_a3: "Inscrivez-vous simplement sur GrowVia, complétez votre profil avec vos objectifs et antécédents, et vous pouvez immédiatement commencer à explorer les mentors.",
    faq_cat2_q1: 'Comment fonctionnent les sessions ?',
    faq_cat2_a1: "Les sessions se déroulent via Google Meet, intégré directement dans la plateforme GrowVia. Une fois que vous réservez une session, un lien unique est automatiquement généré et partagé avec vous et votre mentor par email.",
    faq_cat2_q2: 'Quelle est la durée des sessions ?',
    faq_cat2_a2: "Les sessions sont disponibles en formats de 30 ou 60 minutes, selon les offres du mentor et votre préférence.",
    faq_cat2_q3: 'Puis-je voir mes sessions à venir et passées ?',
    faq_cat2_a3: "Oui. Votre calendrier personnel et votre historique de sessions sont disponibles dans Mon Espace.",
    faq_cat3_q1: 'Comment fonctionne le paiement ?',
    faq_cat3_a1: "Après avoir choisi un mentor et sélectionné un créneau, vous êtes guidé vers un paiement sécurisé via Stripe. La Session Découverte coûte 9,99€ (unique). Les plans mensuels se renouvellent mensuellement et peuvent être annulés à tout moment.",
    faq_cat3_q2: 'Le paiement est-il sécurisé ?',
    faq_cat3_a2: "Absolument. Tous les paiements sont traités via Stripe, qui utilise le chiffrement TLS de niveau bancaire. GrowVia ne stocke jamais vos informations de carte.",
    faq_cat3_q3: "Qu'incluent les plans d'abonnement ?",
    faq_cat3_a3: "Basique (19,99€/mois) inclut 2 sessions/mois et 1 utilisation de Matching IA. Premium (39,99€/mois) inclut 4 sessions/mois, Matching IA illimité, réservation prioritaire et recommandations personnalisées.",
    faq_cat3_q4: 'Y a-t-il des frais cachés ?',
    faq_cat3_a4: "Non. Le prix que vous voyez est le prix que vous payez. Tous les prix incluent la TVA applicable. Il n'y a pas de frais de configuration, d'annulation ou de frais cachés.",
    faq_cat4_q1: 'Puis-je annuler une session réservée ?',
    faq_cat4_a1: "Oui. Vous pouvez annuler une session à tout moment, mais vous devez le faire au moins 1 heure avant l'heure de début prévue.",
    faq_cat4_q2: "Serai-je remboursé si j'annule ?",
    faq_cat4_a2: "Non. Notre politique d'annulation n'inclut pas de remboursements. Si vous annulez plus d'1 heure à l'avance, votre crédit de session peut être retourné selon votre plan.",
    faq_cat5_q1: 'Comment les mentors sont-ils sélectionnés ?',
    faq_cat5_a1: "Chaque mentor sur GrowVia passe par un processus d'approbation manuel. Seuls les mentors vérifiés apparaissent sur la plateforme.",
    faq_cat5_q2: 'Puis-je enregistrer des mentors qui me plaisent ?',
    faq_cat5_a2: "Oui. Vous pouvez ajouter des mentors à vos favoris en cliquant sur l'icône cœur. Vos mentors enregistrés sont accessibles depuis Mon Espace.",
    faq_cat5_q3: "Que faire si je ne suis pas satisfait de mon match ?",
    faq_cat5_a3: "Si le match IA ne vous convient pas, vous pouvez parcourir notre annuaire complet de mentors et en choisir un différent.",
    faq_cat6_q1: 'Comment mon école peut-elle utiliser GrowVia ?',
    faq_cat6_a1: "Les écoles peuvent créer un compte institutionnel et inviter des étudiants via un lien dédié. Les étudiants qui s'inscrivent avec leur email scolaire sont automatiquement liés.",
    faq_cat6_q2: 'Comment les étudiants accèdent-ils via leur école ?',
    faq_cat6_a2: "Votre école enverra un lien d'invitation aux étudiants. Ils s'inscrivent avec leur email scolaire et sont automatiquement connectés à Mon Espace de votre institution.",
    faq_still: 'Vous avez encore des questions ?',
    faq_still_sub: "Notre équipe est heureuse de vous aider. Contactez-nous et nous vous répondrons rapidement.",
    faq_still_cta: 'Nous Contacter',

