    // Who We Are page
    wwa_badge: 'Nuestra Historia',
    wwa_hero_title1: 'Construido por personas que también',
    wwa_hero_title2: 'estuvieron perdidas',
    wwa_hero_sub: 'GrowVia nació de una simple frustración: personas talentosas y ambiciosas tomaban decisiones de carrera a ciegas. Decidimos cambiar eso.',
    wwa_mission_label: 'Nuestra Misión',
    wwa_mission_title: 'Conectar generaciones y liberar el potencial',
    wwa_mission_p1: 'Demasiados estudiantes y jóvenes profesionales enfrentan el mismo desafío: tienen ambición, pero carecen de dirección.',
    wwa_mission_p2: 'Al mismo tiempo, hay miles de profesionales experimentados que quieren devolver, compartir su conocimiento y marcar una diferencia real.',
    wwa_mission_p3: 'GrowVia cierra esa brecha. Creamos las condiciones para relaciones de mentoría genuinas, estructuradas e impactantes.',
    wwa_stat_founded: 'Año de Fundación',
