    wwa_vision_label: 'Nuestra Visión',
    wwa_vision_title: 'Convertirnos en la referencia global de mentoría de calidad',
    wwa_vision_sub: 'Estamos construyendo más que una plataforma. Estamos creando un movimiento donde cada persona ambiciosa tiene acceso a la orientación que necesita.',
    wwa_vision_quote: '"GrowVia no es solo mentoría. Es traer claridad a tu futuro."',
    wwa_founders_title: 'Conoce a las Fundadoras',
    wwa_founders_sub: 'Dos personas en una misión para cambiar cómo el mundo aborda la orientación profesional.',
    wwa_founder1_bio: 'Luna experimentó de primera mano la confusión de elegir un camino profesional. Incapaz de encontrar mentores que realmente entendieran su trayectoria, decidió construir la plataforma que deseaba.',
    wwa_founder2_bio: 'Yasmine aporta pasión por el diseño centrado en el ser humano y la construcción de comunidades. Habiendo trabajado en múltiples países, entiende las complejidades del mercado laboral global.',
    wwa_values_title: 'En lo que creemos',
    wwa_values_sub: 'Los principios que guían cada decisión que tomamos en GrowVia.',
    wwa_value1_title: 'Primero las Personas',
    wwa_value1_desc: 'Cada interacción en GrowVia se construye alrededor de la conexión humana real. Creemos que la orientación más poderosa viene de personas que verdaderamente se preocupan.',
    wwa_value2_title: 'Claridad Sobre el Ruido',
