    // FAQ page
    faq_badge: 'Preguntas',
    faq_title1: 'Preguntas',
    faq_title2: 'frecuentes',
    faq_sub: 'Todo lo que necesitas saber sobre GrowVia. ¿No encuentras tu respuesta? Contáctanos directamente.',
    faq_cat1: 'Primeros Pasos',
    faq_cat2: 'Sesiones y Reservas',
    faq_cat3: 'Precios y Pagos',
    faq_cat4: 'Política de Cancelación',
    faq_cat5: 'Mentores',
    faq_cat6: 'Para Escuelas',
    faq_cat1_q1: '¿Cómo empiezo en GrowVia?',
    faq_cat1_a1: 'Regístrate, completa tu perfil y reserva una Sesión de Descubrimiento por 9,99€. Esta sesión de introducción de 15–20 minutos te permite conocer a un mentor y probar nuestro Matching IA una vez. No se requiere compromiso a largo plazo.',
    faq_cat1_q2: '¿Necesito una cuenta para ver mentores?',
    faq_cat1_a2: 'Necesitas crear un perfil para acceder a nuestro directorio completo de mentores y usar el matching IA. Crear un perfil es gratuito y toma unos 5 minutos.',
    faq_cat1_q3: '¿Cómo me convierto en aprendiz?',
    faq_cat1_a3: 'Simplemente regístrate en GrowVia, completa tu perfil con tus objetivos y antecedentes, y puedes comenzar a explorar mentores inmediatamente.',
    faq_cat2_q1: '¿Cómo funcionan las sesiones?',
    faq_cat2_a1: 'Las sesiones se realizan via Google Meet, integrado directamente en la plataforma GrowVia. Una vez que reservas, se genera automáticamente un enlace único y se comparte con tu mentor por correo.',
    faq_cat2_q2: '¿Cuánto duran las sesiones?',
    faq_cat2_a2: 'Las sesiones están disponibles en formatos de 30 o 60 minutos, según las ofertas del mentor y tu preferencia.',
    faq_cat2_q3: '¿Puedo ver mis sesiones próximas y pasadas?',
    faq_cat2_a3: 'Sí. Tu calendario personal e historial de sesiones están disponibles en tu panel. Puedes ver sesiones próximas, pasadas y su estado.',
    faq_cat3_q1: '¿Cómo funciona el pago?',
    faq_cat3_a1: 'Después de elegir un mentor y seleccionar un horario, se te guía a través de un pago seguro impulsado por Stripe. La Sesión de Descubrimiento cuesta 9,99€ (una vez). Los planes mensuales se renuevan mensualmente y se pueden cancelar en cualquier momento.',
    faq_cat3_q2: '¿Es seguro el pago?',
    faq_cat3_a2: 'Absolutamente. Todos los pagos se procesan a través de Stripe, que usa cifrado TLS de nivel bancario. GrowVia nunca almacena tu información de tarjeta.',
    faq_cat3_q3: '¿Qué incluyen los planes de suscripción?',
    faq_cat3_a3: 'Básico (19,99€/mes) incluye 2 sesiones/mes y 1 uso de Matching IA. Premium (39,99€/mes) incluye 4 sesiones/mes, Matching IA ilimitado, reserva prioritaria y recomendaciones personalizadas.',
    faq_cat3_q4: '¿Hay cargos ocultos?',
    faq_cat3_a4: 'No. El precio que ves es el precio que pagas. Todos los precios incluyen IVA aplicable. No hay tarifas de configuración, cancelación ni cargos ocultos.',
    faq_cat4_q1: '¿Puedo cancelar una sesión reservada?',
    faq_cat4_a1: 'Sí. Puedes cancelar una sesión en cualquier momento, pero debes hacerlo al menos 1 hora antes de la hora de inicio programada.',
    faq_cat4_q2: '¿Recibiré un reembolso si cancelo?',
    faq_cat4_a2: 'No. Nuestra política de cancelación no incluye reembolsos. Si cancelas con más de 1 hora de antelación, tu crédito de sesión puede devolverse según tu plan.',
    faq_cat5_q1: '¿Cómo se seleccionan los mentores?',
    faq_cat5_a1: 'Cada mentor en GrowVia pasa por un proceso de aprobación manual. Solo los mentores verificados aparecen en la plataforma.',
    faq_cat5_q2: '¿Puedo guardar mentores que me gusten?',
    faq_cat5_a2: 'Sí. Puedes añadir mentores a tus favoritos haciendo clic en el ícono de corazón. Tus mentores guardados están accesibles desde tu panel.',
    faq_cat5_q3: '¿Qué pasa si no estoy satisfecho con mi match?',
    faq_cat5_a3: 'Si el match IA no se siente bien, puedes explorar nuestro directorio completo de mentores y elegir uno diferente.',
    faq_cat6_q1: '¿Cómo puede mi escuela usar GrowVia?',
    faq_cat6_a1: 'Las escuelas pueden crear una cuenta institucional e invitar a estudiantes via un enlace dedicado. Los estudiantes que se registran con su correo escolar se vinculan automáticamente.',
    faq_cat6_q2: '¿Cómo acceden los estudiantes a través de su escuela?',
    faq_cat6_a2: 'Tu escuela enviará un enlace de invitación a los estudiantes. Se registran con su correo escolar y se conectan automáticamente al panel de tu institución.',
    faq_still: '¿Aún tienes preguntas?',
    faq_still_sub: 'Nuestro equipo estará encantado de ayudarte. Escríbenos y te responderemos rápidamente.',
    faq_still_cta: 'Contáctanos',

