    safety_sessions_title: 'Sesiones seguras',
    safety_sessions_sub: 'Cada sesión está estructurada, registrada en nuestro sistema y apoyada por nuestro equipo.',
    safety_s1_title: 'Privado y Confidencial',
    safety_s1_desc: 'Los detalles de la sesión son privados entre el mentor y el aprendiz. Respetamos la confidencialidad de cada conversación.',
    safety_s2_title: 'Historial Transparente',
    safety_s2_desc: 'Ambas partes tienen acceso a su historial de sesiones. El estado de la sesión siempre es visible.',
    safety_s3_title: 'Protección de Identidad',
    safety_s3_desc: 'Protegemos la información personal de acuerdo con el RGPD. Tus datos nunca se venden ni se comparten con terceros.',
    safety_s4_title: 'Sistema de Reporte',
    safety_s4_desc: 'Cualquier usuario puede reportar comportamiento inapropiado en cualquier momento. Los reportes son revisados dentro de 24 horas.',
    safety_s5_title: 'Política de Tolerancia Cero',
    safety_s5_desc: 'Tenemos tolerancia cero para el acoso, la discriminación o la conducta inapropiada. Las violaciones resultan en suspensión inmediata.',
    safety_s6_title: 'Soporte Disponible',
    safety_s6_desc: 'Nuestro equipo de soporte está disponible si alguna vez te sientes incómodo o necesitas asistencia antes, durante o después de una sesión.',
    safety_data_title: 'Protección de datos',
    safety_data_sub: 'GrowVia cumple plenamente con el RGPD y se toma en serio tu privacidad.',
    safety_d1: 'Tus datos personales están almacenados de forma segura en servidores cifrados',
