    // Founders page
    founders_label: 'Gründerinnen · GrowVia',
    founders_hero_title: 'Wir beschleunigen die besten Karrieren der Welt durch Mentoring, Netzwerk und Expertise.',
    founders_hero_sub: 'GrowVia verbindet ehrgeizige Fachleute mit erstklassigen Mentoren durch KI – in Minuten, nicht Monaten.',
    founders_hero_cta: 'Bei GrowVia bewerben',
    founders_reason_label: 'Unser Daseinszweck',
    founders_reason_title: 'Zwei Managementstudierende, die Mentoren suchten – und beschlossen, das Fehlende zu bauen.',
    founders_reason_sub: 'Weil die richtige Verbindung im richtigen Moment alles verändern kann.',
    founders_vision_label: 'Unsere Vision',
    founders_vision_quote: 'Wir glauben, dass die Verbindung verschiedener Generationen eine neue Denkweise schafft, bei der Weisheit auf Ehrgeiz trifft und Erfahrung Wachstum beschleunigt.',
    founders_vision_c1_title: 'Jeden Tag wachsen',
    founders_vision_c1_desc: 'Setze dich für kontinuierliche persönliche und berufliche Entwicklung ein. Fortschritt, auch kleiner, ist die einzige Richtung.',
    founders_vision_c2_title: 'Veränderung annehmen',
    founders_vision_c2_desc: 'Passe dich Herausforderungen an und treibe aktiv den Fortschritt voran. Der beste Weg ist selten der offensichtlichste.',
    founders_vision_c3_title: 'Vertrauen aufbauen',
    founders_vision_c3_desc: 'Pflege ehrliche und transparente Beziehungen, die echte Wirkung erzielen. Vertrauen ist das Fundament jeder großen Mentoring-Verbindung.',
    founders_history_label: 'Unsere Geschichte',
    founders_history_title: 'Aus echter Frustration entstanden.',
    founders_history_text: 'GrowVia entstand aus echter Frustration. Luna fand keine Mentoren, die ihren Weg wirklich verstanden. Yasmine sah erfahrene Fachleute ohne Möglichkeit, etwas zurückzugeben. Gemeinsam beschlossen sie, die Plattform zu bauen, die sie sich gewünscht hätten.',
    founders_stories_label: 'Geschichten',
    founders_stories_title: 'Worte, die zählen.',
    founders_video_label: 'Unsere Geschichte ansehen',
    founders_partner_title: 'Partner werden.',
    founders_partner_cta: 'Kontakt aufnehmen',
    founders_team_label: 'Das Team',
    founders_team_title: 'Lerne die Gründerinnen kennen.',
    founders_mission_label: 'Unsere Mission',
    founders_mission_title: 'Generationen verbinden und Potenzial freisetzen.',
    founders_mission_p1: 'Zu viele Studierende und junge Berufstätige stehen vor derselben Herausforderung: Sie haben Ehrgeiz, aber keine Orientierung. Sie fühlen sich von Entscheidungen überwältigt, sind sich ihrer Stärken unsicher und finden niemanden, der ihre Situation wirklich versteht.',
    founders_mission_p2: 'Gleichzeitig gibt es Tausende erfahrener Fachleute, die etwas zurückgeben, ihr Wissen teilen und einen echten Unterschied in der Karriere anderer machen möchten.',
    founders_mission_p3: 'GrowVia überbrückt diese Lücke und schafft die Bedingungen für echte, strukturierte und wirkungsvolle Mentoring-Beziehungen.',
    founders_stat_founded: 'Gründungsjahr',
    founders_stat_hq: 'Hauptsitz',
    founders_stat_langs: 'Sprachen',
    founders_stat_vision: 'Vision',
    founders_values_label: 'Unsere Werte',
    founders_values_title: 'Prinzipien, die uns leiten.',
    founders_stat_hq_value: 'Barcelona',
    founders_cta_label: 'Mach mit',
    founders_cta_title: 'Begleite uns auf dieser Reise.',
    founders_cta_sub: 'Ob du wachsen oder etwas zurückgeben möchtest – bei GrowVia ist ein Platz für dich.',
    founders_cta_start: 'Loslegen',
    founders_cta_contact: 'Kontaktiere uns',
    founders_founder1_bio: 'Luna hat am eigenen Leib erfahren, wie verwirrend die Wahl eines Karrierewegs nach dem Studium sein kann. Da sie keine Mentoren fand, die ihren Werdegang wirklich verstanden, beschloss sie, die Plattform zu bauen, die sie sich gewünscht hätte.',
    founders_founder2_bio: 'Yasmine bringt eine tiefe Leidenschaft für menschenzentriertes Design und den Aufbau von Communities mit. Da sie in mehreren Ländern und Branchen gearbeitet hat, versteht sie die Komplexität des globalen Arbeitsmarkts.',
    founders_value1_title: 'Jeden Tag wachsen',
    founders_value1_desc: 'Setze dich für kontinuierliche persönliche und berufliche Entwicklung ein. Fortschritt, auch kleiner, ist die einzige Richtung.',
    founders_value2_title: 'Veränderung annehmen',
    founders_value2_desc: 'Passe dich Herausforderungen an und treibe aktiv den Fortschritt voran. Der beste Weg ist selten der offensichtlichste.',
    founders_value3_title: 'Vertrauen aufbauen',
    founders_value3_desc: 'Pflege ehrliche und transparente Beziehungen, die echte Wirkung erzielen. Vertrauen ist das Fundament jeder großen Mentoring-Verbindung.',
