    wwa_stat_langs: 'Unterstützte Sprachen',
    wwa_stat_vision: 'Vision',
    wwa_vision_label: 'Unsere Vision',
    wwa_vision_title: 'Die globale Referenz für hochwertiges Mentoring werden',
    wwa_vision_sub: 'Wir bauen mehr als eine Plattform. Wir schaffen eine Bewegung, in der jede ehrgeizige Person Zugang zu der Orientierung hat, die sie braucht, um ihr volles Potenzial zu entfalten.',
    wwa_vision_quote: '"GrowVia ist nicht nur Mentoring. Es bringt Klarheit in deine Zukunft."',
    wwa_founders_title: 'Lerne die Gründerinnen kennen',
    wwa_founders_sub: 'Zwei Menschen mit der Mission, die Art und Weise zu verändern, wie die Welt Karriereberatung angeht.',
    wwa_founder1_bio: 'Luna hat am eigenen Leib erfahren, wie verwirrend die Wahl eines Karrierewegs nach dem Studium sein kann. Da sie keine Mentoren fand, die ihren Werdegang wirklich verstanden, beschloss sie, die Plattform zu bauen, die sie sich gewünscht hätte.',
    wwa_founder2_bio: 'Yasmine bringt eine tiefe Leidenschaft für menschenzentriertes Design und den Aufbau von Communities mit. Da sie in mehreren Ländern und Branchen gearbeitet hat, versteht sie die Komplexität des globalen Arbeitsmarkts.',
    wwa_values_title: 'Woran wir glauben',
    wwa_values_sub: 'Die Prinzipien, die jede Entscheidung bei GrowVia leiten.',
    wwa_value1_title: 'Mensch zuerst',
    wwa_value1_desc: 'Jede Interaktion auf GrowVia basiert auf echter menschlicher Verbindung. Wir glauben, dass die wirkungsvollste Orientierung von Menschen kommt, die wirklich fürsorglich sind.',
    wwa_value2_title: 'Klarheit statt Rauschen',
    wwa_value2_desc: 'Wir durchschneiden die Verwirrung. Jede Session endet mit konkreten nächsten Schritten, nicht nur mit Inspiration.',
    wwa_value3_title: 'Zugänglich für alle',
    wwa_value3_desc: 'Karriereberatung sollte kein Privileg sein. Wir arbeiten daran, hochwertiges Mentoring für Studierende und Fachleute überall zugänglich zu machen.',
    wwa_value4_title: 'Kontinuierliches Wachstum',
    wwa_value4_desc: 'Wir glauben an lebenslanges Lernen für alle auf der Plattform – sowohl Mentoren als auch Mentees.',
    wwa_cta_title: 'Begleite uns auf dieser Reise',
    wwa_cta_sub: 'Ob du wachsen oder etwas zurückgeben möchtest – bei GrowVia ist ein Platz für dich.',
    wwa_cta_start: 'Loslegen',
    wwa_cta_contact: 'Kontaktiere uns',

