    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Häufig gestellte',
    faq_title2: 'Fragen',
    faq_sub: 'Alles, was du über GrowVia wissen musst. Keine Antwort gefunden? Kontaktiere uns direkt.',
    faq_cat1: 'Einstieg',
    faq_cat2: 'Sessions & Buchung',
    faq_cat3: 'Preise & Zahlungen',
    faq_cat4: 'Stornierungsrichtlinie',
    faq_cat5: 'Mentoren',
    faq_cat6: 'Für Schulen',
    faq_cat1_q1: 'Wie starte ich bei GrowVia?',
    faq_cat1_a1: 'Registriere dich, vervollständige dein Profil und buche eine Entdeckungssession für 9,99€. Diese 15–20-minütige Intro-Session lässt dich einen Mentor kennenlernen und unser KI Smart Matching einmal ausprobieren. Keine langfristige Verpflichtung erforderlich.',
    faq_cat1_q2: 'Brauche ich ein Konto, um Mentoren zu durchsuchen?',
    faq_cat1_a2: 'Du musst ein Profil erstellen, um auf unser vollständiges Mentor-Verzeichnis zuzugreifen und KI-Matching zu nutzen. Die Profilerstellung ist kostenlos und dauert etwa 5 Minuten.',
    faq_cat1_q3: 'Wie werde ich Mentee?',
    faq_cat1_a3: 'Melde dich einfach bei GrowVia an, vervollständige dein Profil mit deinen Zielen und deinem Hintergrund, und du kannst sofort Mentoren durchsuchen und deine erste kostenlose Session buchen.',
    faq_cat2_q1: 'Wie funktionieren Sessions?',
    faq_cat2_a1: 'Sessions finden über Google Meet statt, das direkt in die GrowVia-Plattform integriert ist. Sobald du eine Session buchst, wird automatisch ein einzigartiger Meeting-Link generiert und per E-Mail mit dir und deinem Mentor geteilt. Du klickst einfach auf den Link, um beizutreten.',
    faq_cat2_q2: 'Wie lange dauern die Sessions?',
    faq_cat2_a2: 'Sessions sind in 30- oder 60-Minuten-Formaten verfügbar, je nach Angebot des Mentors und deiner Präferenz.',
    faq_cat2_q3: 'Kann ich meine kommenden und vergangenen Sessions sehen?',
    faq_cat2_a3: 'Ja. Dein persönlicher Kalender und deine Session-Historie sind in deinem Dashboard verfügbar. Du kannst kommende Sessions, vergangene Sessions und deren Status sehen (bevorstehend, abgeschlossen oder storniert).',
    faq_cat3_q1: 'Wie funktioniert die Zahlung?',
    faq_cat3_a1: 'Nach der Wahl eines Mentors und einer Uhrzeit wirst du durch einen sicheren Checkout von Stripe geführt. Die Entdeckungssession kostet 9,99€ (einmalig). Monatliche Pläne werden monatlich erneuert und können jederzeit gekündigt werden.',
    faq_cat3_q2: 'Ist die Zahlung sicher?',
    faq_cat3_a2: 'Absolut. Alle Zahlungen werden über Stripe abgewickelt, das bankgradige TLS-Verschlüsselung verwendet. GrowVia speichert niemals deine Kartendaten auf unseren Servern. Deine Finanzdaten sind immer geschützt.',
    faq_cat3_q3: 'Was ist in den Abonnementplänen enthalten?',
    faq_cat3_a3: 'Basic (4,99€/Monat) umfasst Zugang zu mehr Mentoren und 2–3 KI-Matchings/Monat. Standard (9,99€/Monat) umfasst Zugang zu den meisten Mentoren, erweitertes KI-Matching und personalisierte Empfehlungen. Premium (14,99€/Monat) umfasst Zugang zu ALLEN Mentoren, unbegrenztes KI-Matching und Prioritätsbuchung. Alle Pläne sind jederzeit kündbar.',
    faq_cat3_q4: 'Gibt es versteckte Gebühren?',
    faq_cat3_a4: 'Nein. Der Preis, den du siehst, ist der Preis, den du zahlst. Alle Preise beinhalten die anfallende Mehrwertsteuer. Es gibt keine Einrichtungsgebühren, Stornierungsgebühren oder versteckte Kosten.',
    faq_cat4_q1: 'Kann ich eine gebuchte Session stornieren?',
    faq_cat4_a1: 'Ja. Du kannst eine Session jederzeit stornieren, musst dies jedoch mindestens 1 Stunde vor dem geplanten Beginn tun. Späte Stornierungen (innerhalb von 1 Stunde vor der Session) werden in deinem Konto vermerkt.',
    faq_cat4_q2: 'Bekomme ich eine Rückerstattung, wenn ich storniere?',
    faq_cat4_a2: 'Nein. Unsere Stornierungsrichtlinie beinhaltet keine Rückerstattungen, unabhängig vom Grund der Stornierung. Wenn du mehr als 1 Stunde im Voraus stornierst, kann dein Session-Guthaben je nach Plan zurückgegeben werden.',
    faq_cat5_q1: 'Wie werden Mentoren ausgewählt?',
    faq_cat5_a1: 'Jeder Mentor auf GrowVia durchläuft einen manuellen Genehmigungsprozess. Sie reichen eine Bewerbung ein, und unser Team prüft ihren Hintergrund, ihre Erfahrung und ihre Motivationen, bevor sie genehmigt werden. Nur verifizierte Mentoren erscheinen auf der Plattform.',
    faq_cat5_q2: 'Kann ich Mentoren speichern, die mir gefallen?',
    faq_cat5_a2: 'Ja. Du kannst Mentoren zu deinen Favoriten hinzufügen, indem du auf das Herz-Symbol in ihrem Profil klickst. Deine gespeicherten Mentoren sind in deinem Dashboard unter "Gespeicherte Mentoren" zugänglich, und du kannst von dort direkt buchen.',
    faq_cat5_q3: 'Was, wenn ich mit meinem Mentor-Match nicht zufrieden bin?',
    faq_cat5_a3: 'Wenn das KI-Match nicht passt, kannst du unser vollständiges Mentor-Verzeichnis durchsuchen und einen anderen Mentor wählen. Abonnenten erhalten unbegrenzte KI-Matching-Versuche.',
    faq_cat6_q1: 'Wie kann meine Schule GrowVia nutzen?',
    faq_cat6_a1: 'Schulen können ein institutionelles Konto erstellen und Studierende über einen dedizierten Link einladen. Studierende, die sich mit ihrer Schul-E-Mail anmelden, werden automatisch mit dem Schulkonto verknüpft. Der Schuladministrator kann dann Sessions, Beteiligung und Gesamtaktivität verfolgen.',
    faq_cat6_q2: 'Wie erhalten Studierende über ihre Schule Zugang?',
    faq_cat6_a2: 'Deine Schule sendet einen Einladungslink an Studierende. Studierende melden sich mit ihrer Schul-E-Mail-Adresse an und werden automatisch mit dem Dashboard deiner Institution verbunden.',
    faq_still: 'Noch Fragen?',
    faq_still_sub: 'Unser Team hilft gerne. Melde dich und wir antworten schnell.',
    faq_still_cta: 'Kontaktiere uns',

