    // AI Smart Matching page
    ai_badge: 'Premium-Funktion',
    ai_title1: 'KI',
    ai_title2: 'Smart Matching',
    ai_sub: 'Höre auf zu raten. Unsere KI analysiert deine Ziele, Persönlichkeit und Erfahrung, um die Mentoren zu empfehlen, die dir am wahrscheinlichsten helfen werden – mit einem Kompatibilitätswert für jeden Match.',
    ai_section_title: 'Den richtigen Mentor zu finden ist das Schwierigste',
    ai_section_p1: 'Die meisten Menschen wählen einen Mentor nach Berufsbezeichnung oder Berufsjahren. Aber die Mentoren, die wirklich helfen, sind die, die deine spezifische Situation, Ziele und Persönlichkeit verstehen.',
    ai_section_p2: 'GrowVias KI Smart Matching geht tiefer. Es berücksichtigt, was du erreichen willst, wie du lernst und welcher Beratungsstil am besten für dich funktioniert.',
