    ai_feat1_desc: 'Die KI analysiert deine Karriereziele, Interessen und Erfahrung, um Mentoren zu finden, die denselben Weg gegangen sind.',
    ai_feat2_title: 'Zeigt Kompatibilitätsprozentsatz',
