    // Mentor Certification page
    cert_badge: 'Mentor-Zertifizierung',
    cert_title1: 'Werde ein GrowVia',
    cert_title2: 'Zertifizierter Mentor',
    cert_sub: 'Alle Mentoren auf GrowVia absolvieren vor dem Live-Gang eine kurze Zertifizierung. Es dauert weniger als eine Stunde und macht den entscheidenden Unterschied.',
    cert_process_label: 'Der Prozess',
    cert_process_title: 'Drei Schritte zur Zertifizierung',
    cert_process_sub: 'Weniger als eine Stunde. Einmal erledigt. Dauerhaft gültig.',
    cert_s1_title: '3 kurze Schulungsvideos ansehen',
    cert_s1_desc: 'Lerne bewährte Techniken für effektives Mentoring, aktives Zuhören, Zielsetzungsrahmen und wie man Feedback gibt, das wirklich ankommt.',
    cert_s2_title: 'Kurze Bewertung abschließen',
    cert_s2_desc: 'Ein kurzes Quiz, um dein Verständnis zu validieren und zu bestätigen, dass du bereit bist, Mentees mit Zuversicht zu führen.',
    cert_s3_title: 'Zertifiziertes Abzeichen verdienen',
    cert_s3_desc: 'Dein öffentliches Profil zeigt das "GrowVia Zertifizierter Mentor"-Abzeichen an, das sofort für Mentees sichtbar ist, die die Plattform durchsuchen.',
    cert_step: 'Schritt',
    cert_impact_label: 'Die Wirkung',
    cert_impact_title: 'Warum es wichtig ist',
    cert_impact_sub: 'Zertifizierung schafft Vertrauen auf beiden Seiten der Beziehung.',
    cert_mentees_label: 'Für Mentees',
    cert_mentees_title: 'Jeder Mentor wurde geprüft und geschult.',
    cert_mentees_desc: 'Du weißt, dass jeder Mentor, dem du begegnest, geprüft und geschult wurde. Kein Raten. Wenn du eine Session mit einem GrowVia Zertifizierten Mentor buchst, arbeitest du mit jemandem zusammen, der weiß, wie man führt, zuhört und dir hilft, voranzukommen.',
    cert_mentors_label: 'Für Mentoren',
    cert_mentors_title: 'Dein Abzeichen signalisiert Glaubwürdigkeit.',
    cert_mentors_desc: 'Dein Abzeichen signalisiert Glaubwürdigkeit und erhöht deine Sichtbarkeit in den Matching-Ergebnissen. Zertifizierte Mentoren erscheinen höher in KI-gestützten Empfehlungen und werden mit größerer Wahrscheinlichkeit von ernsthaften Mentees gebucht.',
    cert_cta_title: 'Bereit zur Zertifizierung?',
    cert_cta_sub: 'Bewerbe dich als Mentor bei GrowVia. Nach der Genehmigung schließt du die Zertifizierung als Teil deines Onboardings ab, bevor deine erste Session live geht.',
    cert_cta_btn: 'Als Mentor bewerben',

    // Safety & Trust page
    safety_badge: 'Sicherheit & Vertrauen',
    safety_title1: 'Deine Sicherheit hat für uns',
    safety_title2: 'höchste Priorität',
    safety_sub: 'GrowVia basiert auf Vertrauen. Jede Funktion, jeder Prozess und jede Entscheidung ist darauf ausgelegt, unsere Community sicher und unterstützt zu halten.',
    safety_verif_label: 'Mentor-Verifizierung',
    safety_verif_title: 'Jeder Mentor wird manuell verifiziert',
    safety_verif_sub: 'Wir lassen niemanden Mentor auf GrowVia werden, ohne unseren Verifizierungsprozess zu durchlaufen.',
    safety_v1_label: 'Bewerbungsprüfung durch unser Team',
    safety_v1_desc: 'Wir lesen jede Bewerbung manuell. Keine automatisierten Genehmigungen.',
    safety_v2_label: 'Beruflicher Hintergrundcheck',
    safety_v2_desc: 'Wir verifizieren berufliche Geschichte und Erfahrungsangaben.',
    safety_v3_label: 'Status: in Prüfung',
    safety_v3_desc: "Mentoren werden als 'in Prüfung' markiert, bis sie genehmigt werden. Nur genehmigte Mentoren erscheinen öffentlich.",
    safety_v4_label: 'Kontinuierliche Qualitätsüberwachung',
    safety_v4_desc: 'Wir überwachen kontinuierlich die Session-Qualität und das Nutzer-Feedback.',
    safety_verif_step1: 'Bewerbung eingereicht',
    safety_verif_step2: 'Beruflicher Hintergrund verifiziert',
    safety_verif_step3: 'Team-Prüfung',
    safety_verif_step4: 'Genehmigt & auf Plattform live',
    safety_verif_badge: 'Verifizierter Mentor',
    safety_sessions_title: 'Sichere Sessions',
    safety_sessions_sub: 'Jede Session ist strukturiert, in unserem System aufgezeichnet und wird von unserem Team unterstützt.',
    safety_s1_title: 'Privat & Vertraulich',
    safety_s1_desc: 'Session-Details sind privat zwischen Mentor und Mentee. Wir respektieren die Vertraulichkeit jedes Gesprächs.',
    safety_s2_title: 'Transparente Geschichte',
    safety_s2_desc: 'Beide Parteien haben Zugang zu ihrer Session-Historie. Session-Status (bevorstehend, abgeschlossen, storniert) ist immer sichtbar.',
    safety_s3_title: 'Identitätsschutz',
    safety_s3_desc: 'Wir schützen persönliche Informationen gemäß DSGVO. Deine Daten werden niemals verkauft oder an Dritte weitergegeben.',
    safety_s4_title: 'Meldesystem',
    safety_s4_desc: 'Jeder Nutzer kann jederzeit unangemessenes Verhalten melden. Berichte werden innerhalb von 24 Stunden von unserem Team geprüft.',
    safety_s5_title: 'Null-Toleranz-Politik',
