    // Who We Are page
    wwa_badge: 'A nossa História',
    wwa_hero_title1: 'Construído por pessoas que também',
    wwa_hero_title2: 'estiveram perdidas',
    wwa_hero_sub: 'A GrowVia nasceu de uma frustração simples: pessoas talentosas e ambiciosas tomavam decisões de carreira às cegas. Decidimos mudar isso.',
    wwa_mission_label: 'A nossa Missão',
    wwa_mission_title: 'Ligar gerações e libertar potencial',
    wwa_mission_p1: 'Demasiados estudantes e jovens profissionais enfrentam o mesmo desafio: têm ambição, mas faltam-lhes orientação.',
    wwa_mission_p2: 'Ao mesmo tempo, há milhares de profissionais experientes que querem retribuir, partilhar o seu conhecimento e fazer uma diferença real na carreira de alguém.',
    wwa_mission_p3: 'A GrowVia preenche essa lacuna. Criamos as condições para relações de mentoria genuínas, estruturadas e com impacto.',
