    wwa_vision_sub: 'Estamos a construir mais do que uma plataforma. Estamos a criar um movimento onde cada pessoa ambiciosa tem acesso à orientação de que necessita para atingir o seu pleno potencial.',
    wwa_vision_quote: '"A GrowVia não é apenas mentoria. É trazer clareza ao teu futuro."',
    wwa_founders_title: 'Conhece as Fundadoras',
    wwa_founders_sub: 'Duas pessoas com a missão de mudar a forma como o mundo aborda a orientação de carreira.',
    wwa_founder1_bio: 'A Luna viveu em primeira mão a confusão de escolher um percurso profissional após os estudos. Incapaz de encontrar mentores que compreendessem verdadeiramente a sua jornada, decidiu construir a plataforma que gostaria de ter tido.',
    wwa_founder2_bio: 'A Yasmine traz uma profunda paixão pelo design centrado nas pessoas e pela construção de comunidades. Tendo trabalhado em vários países e sectores, compreende as complexidades de navegar num mercado de trabalho global.',
    wwa_values_title: 'No que acreditamos',
    wwa_values_sub: 'Os princípios que guiam cada decisão que tomamos na GrowVia.',
    wwa_value1_title: 'Pessoas em Primeiro',
    wwa_value1_desc: 'Cada interacção na GrowVia é construída em torno de uma ligação humana genuína. Acreditamos que a orientação mais poderosa vem de pessoas que realmente se importam.',
    wwa_value2_title: 'Clareza em vez de Ruído',
