    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Perguntas',
    faq_title2: 'frequentes',
    faq_sub: 'Tudo o que precisas de saber sobre a GrowVia. Não encontraste a resposta? Contacta-nos directamente.',
    faq_cat1: 'Primeiros Passos',
    faq_cat2: 'Sessões e Reservas',
    faq_cat3: 'Preços e Pagamentos',
    faq_cat4: 'Política de Cancelamento',
    faq_cat5: 'Mentores',
    faq_cat6: 'Para Escolas',
    faq_cat1_q1: 'Como começo na GrowVia?',
    faq_cat1_a1: 'Regista-te, completa o teu perfil e reserva uma Sessão de Descoberta por 9,99€. Esta sessão de introdução de 15–20 minutos permite-te conhecer um mentor e experimentar a funcionalidade de Matching IA uma vez. Não é necessário compromisso a longo prazo.',
    faq_cat1_q2: 'Preciso de uma conta para ver os mentores?',
    faq_cat1_a2: 'Precisas de criar um perfil para aceder ao nosso directório completo de mentores e usar o matching IA. Criar um perfil é gratuito e demora cerca de 5 minutos.',
    faq_cat1_q3: 'Como me torno mentee?',
    faq_cat1_a3: 'Regista-te na GrowVia, completa o teu perfil com os teus objetivos e historial, e podes imediatamente começar a explorar mentores e reservar a tua primeira sessão gratuita.',
    faq_cat2_q1: 'Como funcionam as sessões?',
    faq_cat2_a1: 'As sessões realizam-se via Google Meet, que está integrado directamente na plataforma GrowVia. Quando reservas uma sessão, é automaticamente gerado um link de reunião único e partilhado contigo e com o teu mentor por email. Basta clicar no link para entrar.',
    faq_cat2_q2: 'Quanto tempo duram as sessões?',
    faq_cat2_a2: 'As sessões estão disponíveis em formatos de 30 ou 60 minutos, dependendo da oferta do mentor e da tua preferência.',
    faq_cat2_q3: 'Posso ver as minhas sessões futuras e passadas?',
    faq_cat2_a3: 'Sim. O teu calendário pessoal e historial de sessões estão disponíveis no teu dashboard. Podes ver sessões futuras, sessões passadas e o seu estado (futura, concluída ou cancelada).',
    faq_cat3_q1: 'Como funciona o pagamento?',
    faq_cat3_a1: 'Depois de escolheres um mentor e seleccionares um horário, és guiado por um checkout seguro gerido pelo Stripe. A Sessão de Descoberta custa 9,99€ (única vez). Os planos mensais renovam-se mensalmente e podem ser cancelados a qualquer momento.',
    faq_cat3_q2: 'O pagamento é seguro?',
    faq_cat3_a2: 'Absolutamente. Todos os pagamentos são processados através do Stripe, que usa encriptação TLS de nível bancário. A GrowVia nunca armazena os dados do teu cartão nos nossos servidores. Os teus dados financeiros estão sempre protegidos.',
    faq_cat3_q3: 'O que está incluído nos planos de subscrição?',
    faq_cat3_a3: 'Basic (4,99€/mês) inclui acesso a mais mentores e 2–3 matchings IA/mês. Standard (9,99€/mês) inclui acesso à maioria dos mentores, matching IA alargado e recomendações personalizadas. Premium (14,99€/mês) inclui acesso a TODOS os mentores, matching IA ilimitado e reserva prioritária. Todos os planos podem ser cancelados a qualquer momento.',
    faq_cat3_q4: 'Existem taxas ocultas?',
    faq_cat3_a4: 'Não. O preço que vês é o preço que pagas. Todos os preços incluem IVA aplicável. Não há taxas de configuração, taxas de cancelamento ou encargos ocultos.',
    faq_cat4_q1: 'Posso cancelar uma sessão reservada?',
    faq_cat4_a1: 'Sim. Podes cancelar uma sessão a qualquer momento, mas tens de o fazer pelo menos 1 hora antes da hora de início prevista. Os cancelamentos tardios (dentro de 1 hora da sessão) ficam registados na tua conta.',
    faq_cat4_q2: 'Recebo reembolso se cancelar?',
    faq_cat4_a2: 'Não. A nossa política de cancelamento não inclui reembolsos, independentemente do motivo do cancelamento. Se cancelares com mais de 1 hora de antecedência, o teu crédito de sessão pode ser devolvido dependendo do teu plano.',
    faq_cat5_q1: 'Como são seleccionados os mentores?',
    faq_cat5_a1: 'Cada mentor na GrowVia passa por um processo de aprovação manual. Submetem uma candidatura e a nossa equipa analisa o seu historial, experiência e motivações antes de os aprovar. Apenas mentores verificados aparecem na plataforma.',
    faq_cat5_q2: 'Posso guardar mentores de que gosto?',
    faq_cat5_a2: 'Sim. Podes adicionar mentores aos teus favoritos clicando no ícone de coração no seu perfil. Os teus mentores guardados estão acessíveis no teu dashboard em Mentores Guardados, e podes reservar directamente a partir daí.',
    faq_cat5_q3: 'E se não estiver satisfeito com o meu match de mentor?',
    faq_cat5_a3: 'Se o match IA não parecer certo, podes navegar pelo nosso directório completo de mentores e escolher um diferente. Os utilizadores com subscrição obtêm tentativas de matching IA ilimitadas.',
    faq_cat6_q1: 'Como pode a minha escola usar a GrowVia?',
    faq_cat6_a1: 'As escolas podem criar uma conta institucional e convidar estudantes através de um link dedicado. Os estudantes que se inscrevem usando o email escolar são automaticamente ligados à conta escolar. O administrador escolar pode então acompanhar sessões, participação e actividade geral.',
    faq_cat6_q2: 'Como obtêm os estudantes acesso através da sua escola?',
    faq_cat6_a2: 'A tua escola enviará um link de convite aos estudantes. Os estudantes inscrevem-se usando o endereço de email escolar e ficam automaticamente ligados ao dashboard da tua instituição.',
    faq_still: 'Ainda tens dúvidas?',
    faq_still_sub: 'A nossa equipa tem todo o gosto em ajudar. Contacta-nos e responderemos rapidamente.',
    faq_still_cta: 'Contactar-nos',

