    // Who We Are page
    wwa_badge: 'Nossa História',
    wwa_hero_title1: 'Construído por pessoas que também',
    wwa_hero_title2: 'estiveram perdidas',
    wwa_hero_sub: 'A GrowVia nasceu de uma frustração simples: pessoas talentosas e ambiciosas tomavam decisões de carreira às cegas. Decidimos mudar isso.',
    wwa_mission_label: 'Nossa Missão',
    wwa_mission_title: 'Conectar gerações e liberar potencial',
    wwa_mission_p1: 'Muitos estudantes e jovens profissionais enfrentam o mesmo desafio: têm ambição, mas lhes falta orientação.',
    wwa_mission_p2: 'Ao mesmo tempo, há milhares de profissionais experientes que querem retribuir, compartilhar seu conhecimento e fazer uma diferença real na carreira de alguém.',
    wwa_mission_p3: 'A GrowVia preenche essa lacuna. Criamos as condições para relações de mentoria genuínas, estruturadas e com impacto.',
    wwa_stat_founded: 'Ano de Fundação',
    wwa_stat_hq: 'Sede',
    wwa_stat_langs: 'Idiomas Suportados',
    wwa_stat_vision: 'Visão',
    wwa_vision_label: 'Nossa Visão',
    wwa_vision_title: 'Tornarmo-nos a referência global para mentoria de qualidade',
    wwa_vision_sub: 'Estamos construindo mais do que uma plataforma. Estamos criando um movimento onde cada pessoa ambiciosa tem acesso à orientação de que precisa para atingir seu pleno potencial.',
    wwa_vision_quote: '"A GrowVia não é apenas mentoria. É trazer clareza ao seu futuro."',
    wwa_founders_title: 'Conheça as Fundadoras',
    wwa_founders_sub: 'Duas pessoas com a missão de mudar a forma como o mundo aborda a orientação de carreira.',
    wwa_founder1_bio: 'A Luna viveu em primeira mão a confusão de escolher um caminho profissional após os estudos. Incapaz de encontrar mentores que compreendessem verdadeiramente sua jornada, decidiu construir a plataforma que gostaria de ter tido.',
    wwa_founder2_bio: 'A Yasmine traz uma profunda paixão pelo design centrado nas pessoas e pela construção de comunidades. Tendo trabalhado em vários países e setores, compreende as complexidades de navegar num mercado de trabalho global.',
    wwa_values_title: 'No que acreditamos',
    wwa_values_sub: 'Os princípios que guiam cada decisão que tomamos na GrowVia.',
    wwa_value1_title: 'Pessoas em Primeiro',
    wwa_value1_desc: 'Cada interação na GrowVia é construída em torno de uma conexão humana genuína. Acreditamos que a orientação mais poderosa vem de pessoas que realmente se importam.',
    wwa_value2_title: 'Clareza em vez de Ruído',
    wwa_value2_desc: 'Cortamos a confusão. Cada sessão termina com próximos passos concretos, não apenas inspiração.',
    wwa_value3_title: 'Acessível a Todos',
    wwa_value3_desc: 'A orientação de carreira não deve ser um privilégio. Trabalhamos para tornar a mentoria de qualidade acessível a estudantes e profissionais em todo lugar.',
    wwa_value4_title: 'Crescimento Contínuo',
    wwa_value4_desc: 'Acreditamos na aprendizagem ao longo da vida para todos na plataforma, mentores e mentees.',
