    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Perguntas',
    faq_title2: 'frequentes',
    faq_sub: 'Tudo o que você precisa saber sobre a GrowVia. Não encontrou a resposta? Entre em contato diretamente.',
    faq_cat1: 'Primeiros Passos',
    faq_cat2: 'Sessões e Agendamentos',
    faq_cat3: 'Preços e Pagamentos',
    faq_cat4: 'Política de Cancelamento',
    faq_cat5: 'Mentores',
    faq_cat6: 'Para Escolas',
    faq_cat1_q1: 'Como começo na GrowVia?',
    faq_cat1_a1: 'Cadastre-se, complete seu perfil e agende uma Sessão de Descoberta por 9,99€. Essa sessão de introdução de 15–20 minutos permite que você conheça um mentor e experimente a funcionalidade de Matching IA uma vez. Não é necessário compromisso a longo prazo.',
    faq_cat1_q2: 'Preciso de uma conta para ver os mentores?',
    faq_cat1_a2: 'Você precisa criar um perfil para acessar nosso diretório completo de mentores e usar o matching IA. Criar um perfil é gratuito e leva cerca de 5 minutos.',
    faq_cat1_q3: 'Como me torno mentee?',
    faq_cat1_a3: 'Cadastre-se na GrowVia, complete seu perfil com seus objetivos e histórico, e você pode imediatamente começar a explorar mentores e agendar sua primeira sessão gratuita.',
    faq_cat2_q1: 'Como funcionam as sessões?',
    faq_cat2_a1: 'As sessões acontecem via Google Meet, que está integrado diretamente na plataforma GrowVia. Quando você agenda uma sessão, é automaticamente gerado um link de reunião único e compartilhado com você e seu mentor por e-mail. Basta clicar no link para entrar.',
    faq_cat2_q2: 'Quanto tempo duram as sessões?',
    faq_cat2_a2: 'As sessões estão disponíveis em formatos de 30 ou 60 minutos, dependendo da oferta do mentor e da sua preferência.',
    faq_cat2_q3: 'Posso ver minhas sessões futuras e passadas?',
    faq_cat2_a3: 'Sim. Seu calendário pessoal e histórico de sessões estão disponíveis no seu dashboard. Você pode ver sessões futuras, sessões passadas e o seu status (futura, concluída ou cancelada).',
    faq_cat3_q1: 'Como funciona o pagamento?',
    faq_cat3_a1: 'Depois de escolher um mentor e selecionar um horário, você é guiado por um checkout seguro gerenciado pelo Stripe. A Sessão de Descoberta custa 9,99€ (única vez). Os planos mensais renovam-se mensalmente e podem ser cancelados a qualquer momento.',
    faq_cat3_q2: 'O pagamento é seguro?',
    faq_cat3_a2: 'Absolutamente. Todos os pagamentos são processados pelo Stripe, que usa criptografia TLS de nível bancário. A GrowVia nunca armazena os dados do seu cartão em nossos servidores. Seus dados financeiros estão sempre protegidos.',
    faq_cat3_q3: 'O que está incluído nos planos de assinatura?',
    faq_cat3_a3: 'Basic (4,99€/mês) inclui acesso a mais mentores e 2–3 matchings IA/mês. Standard (9,99€/mês) inclui acesso à maioria dos mentores, matching IA ampliado e recomendações personalizadas. Premium (14,99€/mês) inclui acesso a TODOS os mentores, matching IA ilimitado e agendamento prioritário. Todos os planos podem ser cancelados a qualquer momento.',
    faq_cat3_q4: 'Existem taxas ocultas?',
    faq_cat3_a4: 'Não. O preço que você vê é o preço que paga. Todos os preços incluem impostos aplicáveis. Não há taxas de configuração, taxas de cancelamento ou encargos ocultos.',
    faq_cat4_q1: 'Posso cancelar uma sessão agendada?',
    faq_cat4_a1: 'Sim. Você pode cancelar uma sessão a qualquer momento, mas deve fazê-lo pelo menos 1 hora antes do horário de início previsto. Os cancelamentos tardios (dentro de 1 hora da sessão) ficam registrados na sua conta.',
    faq_cat4_q2: 'Recebo reembolso se cancelar?',
    faq_cat4_a2: 'Não. Nossa política de cancelamento não inclui reembolsos, independentemente do motivo do cancelamento. Se você cancelar com mais de 1 hora de antecedência, seu crédito de sessão pode ser devolvido dependendo do seu plano.',
    faq_cat5_q1: 'Como os mentores são selecionados?',
    faq_cat5_a1: 'Cada mentor na GrowVia passa por um processo de aprovação manual. Eles enviam uma candidatura e nossa equipe analisa seu histórico, experiência e motivações antes de aprová-los. Apenas mentores verificados aparecem na plataforma.',
    faq_cat5_q2: 'Posso salvar mentores de que gosto?',
    faq_cat5_a2: 'Sim. Você pode adicionar mentores aos seus favoritos clicando no ícone de coração no perfil deles. Seus mentores salvos estão acessíveis no seu dashboard em Mentores Salvos, e você pode agendar diretamente a partir daí.',
    faq_cat5_q3: 'E se eu não estiver satisfeito com meu match de mentor?',
    faq_cat5_a3: 'Se o match IA não parecer certo, você pode navegar por nosso diretório completo de mentores e escolher um diferente. Os usuários com assinatura obtêm tentativas de matching IA ilimitadas.',
    faq_cat6_q1: 'Como minha escola pode usar a GrowVia?',
    faq_cat6_a1: 'As escolas podem criar uma conta institucional e convidar estudantes por meio de um link dedicado. Os estudantes que se cadastram usando o e-mail escolar são automaticamente vinculados à conta escolar. O administrador escolar pode então acompanhar sessões, participação e atividade geral.',
    faq_cat6_q2: 'Como os estudantes obtêm acesso pela escola?',
    faq_cat6_a2: 'Sua escola enviará um link de convite aos estudantes. Os estudantes se cadastram usando o endereço de e-mail escolar e ficam automaticamente vinculados ao dashboard da sua instituição.',
    faq_still: 'Ainda tem dúvidas?',
    faq_still_sub: 'Nossa equipe terá prazer em ajudar. Entre em contato e responderemos rapidamente.',
    faq_still_cta: 'Fale conosco',

