    // Who We Are page
    wwa_badge: 'La nostra storia',
    wwa_hero_title1: 'Costruito da persone che erano',
    wwa_hero_title2: 'anche loro perse un tempo',
    wwa_hero_sub: 'GrowVia è nata da una semplice frustrazione: persone di talento e ambiziose prendevano decisioni di carriera al buio. Abbiamo deciso di cambiarlo.',
    wwa_mission_label: 'La nostra missione',
    wwa_mission_title: 'Connettere generazioni e sbloccare il potenziale',
    wwa_mission_p1: 'Troppi studenti e giovani professionisti affrontano la stessa sfida: hanno ambizione, ma mancano di direzione.',
    wwa_mission_p2: 'Allo stesso tempo, ci sono migliaia di professionisti esperti che vogliono restituire, condividere le proprie conoscenze e fare una vera differenza nella carriera di qualcun altro.',
    wwa_mission_p3: 'GrowVia colma quel divario. Creiamo le condizioni per relazioni di mentoring genuine, strutturate e ad alto impatto.',
    wwa_stat_founded: 'Anno di fondazione',
    wwa_stat_hq: 'Sede',
    wwa_stat_langs: 'Lingue supportate',
    wwa_stat_vision: 'Visione',
    wwa_vision_label: 'La nostra visione',
    wwa_vision_title: 'Diventare il riferimento globale per il mentoring di qualità',
    wwa_vision_sub: 'Stiamo costruendo più di una piattaforma. Stiamo creando un movimento in cui ogni persona ambiziosa ha accesso alla guida necessaria per raggiungere il proprio pieno potenziale.',
    wwa_vision_quote: '"GrowVia non è solo mentoring. È portare chiarezza al tuo futuro."',
    wwa_founders_title: 'Incontra le Fondatrici',
    wwa_founders_sub: 'Due persone in missione per cambiare il modo in cui il mondo affronta l\'orientamento professionale.',
    wwa_founder1_bio: 'Luna ha vissuto in prima persona la confusione di scegliere un percorso professionale dopo la laurea. Non riuscendo a trovare mentor che capissero davvero il suo cammino, ha deciso di costruire la piattaforma che avrebbe voluto esistesse.',
    wwa_founder2_bio: "Yasmine porta una profonda passione per il design centrato sull'utente e la costruzione di community. Avendo lavorato in diversi paesi e settori, comprende le complessità di orientarsi in un mercato del lavoro globale.",
    wwa_values_title: 'In cosa crediamo',
    wwa_values_sub: 'I principi che guidano ogni decisione che prendiamo in GrowVia.',
    wwa_value1_title: 'Prima l\'Umano',
    wwa_value1_desc: 'Ogni interazione su GrowVia è costruita intorno alla vera connessione umana. Crediamo che la guida più potente venga da persone che si preoccupano davvero.',
    wwa_value2_title: 'Chiarezza sul Rumore',
    wwa_value2_desc: 'Tagliamo la confusione. Ogni sessione termina con passi concreti, non solo ispirazione.',
    wwa_value3_title: 'Accessibile a Tutti',
    wwa_value3_desc: 'L\'orientamento professionale non dovrebbe essere un privilegio. Lavoriamo per rendere il mentoring di qualità disponibile a studenti e professionisti ovunque.',
    wwa_value4_title: 'Crescita Continua',
    wwa_value4_desc: 'Crediamo nell\'apprendimento continuo per tutti sulla piattaforma, mentor e mentee.',
