    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Domande',
    faq_title2: 'frequenti',
    faq_sub: 'Tutto quello che devi sapere su GrowVia. Non trovi la tua risposta? Contattaci direttamente.',
    faq_cat1: 'Per iniziare',
    faq_cat2: 'Sessioni e prenotazioni',
    faq_cat3: 'Prezzi e pagamenti',
    faq_cat4: 'Politica di cancellazione',
    faq_cat5: 'Mentor',
    faq_cat6: 'Per le scuole',
    faq_cat1_q1: 'Come inizio su GrowVia?',
    faq_cat1_a1: 'Iscriviti, completa il tuo profilo e prenota una Sessione di Scoperta a 9,99€. Questa sessione di 15–20 minuti ti permette di incontrare un mentor e provare la funzione AI Smart Matching una volta. Nessun impegno a lungo termine richiesto.',
    faq_cat1_q2: 'Ho bisogno di un account per sfogliare i mentor?',
    faq_cat1_a2: 'Devi creare un profilo per accedere alla nostra directory completa di mentor e utilizzare il matching AI. Creare un profilo è gratuito e richiede circa 5 minuti.',
    faq_cat1_q3: 'Come divento un mentee?',
    faq_cat1_a3: 'Basta registrarsi su GrowVia, completare il profilo con i tuoi obiettivi e background, e puoi subito iniziare a sfogliare i mentor e prenotare la tua prima sessione gratuita.',
    faq_cat2_q1: 'Come funzionano le sessioni?',
    faq_cat2_a1: 'Le sessioni si svolgono tramite Google Meet, integrato direttamente nella piattaforma GrowVia. Una volta prenotata la sessione, un link univoco viene generato automaticamente e condiviso con te e il tuo mentor via email. Clicca il link per accedere.',
    faq_cat2_q2: 'Quanto durano le sessioni?',
    faq_cat2_a2: 'Le sessioni sono disponibili in formati da 30 o 60 minuti, a seconda delle offerte del mentor e delle tue preferenze.',
    faq_cat2_q3: 'Posso vedere le mie sessioni future e passate?',
    faq_cat2_a3: 'Sì. Il tuo calendario personale e la cronologia delle sessioni sono disponibili nella tua dashboard. Puoi vedere le sessioni future, quelle passate e il loro stato (in arrivo, completata o annullata).',
    faq_cat3_q1: 'Come funzionano i pagamenti?',
    faq_cat3_a1: 'Dopo aver scelto un mentor e selezionato un orario, vieni guidato attraverso un checkout sicuro powered by Stripe. La Sessione di Scoperta costa 9,99€ (una tantum). I piani mensili si rinnovano mensilmente e possono essere cancellati in qualsiasi momento.',
    faq_cat3_q2: 'I pagamenti sono sicuri?',
    faq_cat3_a2: 'Assolutamente. Tutti i pagamenti vengono elaborati tramite Stripe, che utilizza la crittografia TLS bancaria. GrowVia non memorizza mai le informazioni della tua carta sui nostri server. I tuoi dati finanziari sono sempre protetti.',
    faq_cat3_q3: 'Cosa è incluso nei piani di abbonamento?',
    faq_cat3_a3: 'Basic (19,99€/mese) include 2 sessioni al mese e 1 utilizzo AI Smart Matching. Premium (39,99€/mese) include 4 sessioni al mese, AI Smart Matching illimitato, prenotazione prioritaria e raccomandazioni personalizzate. Entrambi i piani possono essere cancellati in qualsiasi momento.',
    faq_cat3_q4: 'Ci sono costi nascosti?',
    faq_cat3_a4: 'No. Il prezzo che vedi è quello che paghi. Tutti i prezzi includono l\'IVA applicabile. Non ci sono costi di avvio, penali di cancellazione o spese nascoste.',
    faq_cat4_q1: 'Posso cancellare una sessione prenotata?',
    faq_cat4_a1: 'Sì. Puoi cancellare una sessione in qualsiasi momento, ma devi farlo almeno 1 ora prima dell\'orario di inizio programmato. Le cancellazioni tardive (entro 1 ora dalla sessione) vengono registrate sul tuo account.',
    faq_cat4_q2: 'Ricevo un rimborso se cancello?',
    faq_cat4_a2: 'No. La nostra politica di cancellazione non prevede rimborsi, indipendentemente dal motivo della cancellazione. Se cancelli con più di 1 ora di anticipo, il credito della sessione potrebbe essere restituito a seconda del tuo piano.',
    faq_cat5_q1: 'Come vengono selezionati i mentor?',
    faq_cat5_a1: 'Ogni mentor su GrowVia passa attraverso un processo di approvazione manuale. Presentano una candidatura e il nostro team esamina il loro background, esperienza e motivazioni prima di approvarli. Solo i mentor verificati appaiono sulla piattaforma.',
    faq_cat5_q2: 'Posso salvare i mentor che mi piacciono?',
    faq_cat5_a2: 'Sì. Puoi aggiungere i mentor ai tuoi preferiti cliccando l\'icona a cuore sul loro profilo. I mentor salvati sono accessibili dalla tua dashboard nella sezione Mentor Salvati, e puoi prenotare direttamente da lì.',
    faq_cat5_q3: 'Cosa succede se non sono soddisfatto del match con il mentor?',
    faq_cat5_a3: 'Se il match AI non sembra giusto, puoi sfogliare la nostra directory completa di mentor e scegliere un mentor diverso. Gli utenti con abbonamento ottengono tentativi di matching AI illimitati.',
    faq_cat6_q1: 'Come può usare GrowVia la mia scuola?',
    faq_cat6_a1: 'Le scuole possono creare un account istituzionale e invitare gli studenti tramite un link dedicato. Gli studenti che si iscrivono con la loro email scolastica vengono automaticamente collegati all\'account scolastico. L\'amministratore scolastico può quindi monitorare le sessioni, la partecipazione e l\'attività complessiva.',
    faq_cat6_q2: 'Come ottengono l\'accesso gli studenti tramite la loro scuola?',
    faq_cat6_a2: 'La tua scuola invierà un link di invito agli studenti. Gli studenti si iscrivono con la loro email scolastica e vengono automaticamente connessi alla dashboard della tua istituzione.',
    faq_still: 'Hai ancora domande?',
    faq_still_sub: 'Il nostro team è felice di aiutarti. Contattaci e ti risponderemo rapidamente.',
    faq_still_cta: 'Contattaci',

