    // FAQ page
    faq_badge: 'よくある質問',
    faq_title1: 'よくある',
    faq_title2: '質問',
    faq_sub: 'GrowViaについて必要な情報をすべてご確認いただけます。お探しの回答が見つからない場合は、直接お問い合わせください。',
    faq_cat1: 'はじめに',
    faq_cat2: 'セッションと予約',
    faq_cat3: '料金とお支払い',
    faq_cat4: 'キャンセルポリシー',
    faq_cat5: 'メンターについて',
    faq_cat6: '学校向け',
    faq_cat1_q1: 'GrowViaを始めるにはどうすればいいですか？',
    faq_cat1_a1: 'サインアップし、プロフィールを作成して、9.99€で体験セッションを予約してください。この15〜20分の体験セッションでメンターと会い、AIスマートマッチング機能を1回試すことができます。長期コミットメントは不要です。',
    faq_cat1_q2: 'メンターを閲覧するにはアカウントが必要ですか？',
    faq_cat1_a2: 'メンターの全ディレクトリにアクセスしてAIマッチングを使用するにはプロフィールの作成が必要です。プロフィールの作成は無料で、約5分で完了します。',
    faq_cat1_q3: 'メンティーになるにはどうすればいいですか？',
    faq_cat1_a3: 'GrowViaに登録し、目標とバックグラウンドを入力したプロフィールを作成するだけで、すぐにメンターの閲覧と最初のセッション予約を始められます。',
    faq_cat2_q1: 'セッションはどのように行われますか？',
    faq_cat2_a1: 'セッションはGrowViaプラットフォームに直接統合されたGoogle Meetを通じて行われます。セッションを予約すると、ユニークなミーティングリンクが自動生成され、あなたとメンターの両方にメールで共有されます。リンクをクリックするだけで参加できます。',
    faq_cat2_q2: 'セッションの長さはどのくらいですか？',
    faq_cat2_a2: 'メンターのオファーとご希望に応じて、30分または60分のセッションをご利用いただけます。',
    faq_cat2_q3: '今後のセッションや過去のセッションを確認できますか？',
    faq_cat2_a3: 'はい。個人カレンダーとセッション履歴はダッシュボードからご確認いただけます。今後のセッション、過去のセッション、およびそのステータス（今後・完了・キャンセル済み）を確認できます。',
    faq_cat3_q1: 'お支払い方法はどうなっていますか？',
    faq_cat3_a1: 'メンターを選んで時間を選択すると、Stripeを使用した安全な決済ページにご案内します。体験セッションは9.99€（一回払い）です。月額プランは毎月自動更新され、いつでもキャンセルできます。',
    faq_cat3_q2: 'お支払いは安全ですか？',
    faq_cat3_a2: 'もちろんです。すべての決済は銀行レベルのTLS暗号化を使用するStripeを通じて処理されます。GrowViaはサーバー上にカード情報を保存することはありません。財務データは常に保護されています。',
    faq_cat3_q3: 'サブスクリプションプランには何が含まれますか？',
    faq_cat3_a3: 'ベーシック（19.99€/月）は月2回のセッションとAIスマートマッチング1回の利用が含まれます。プレミアム（39.99€/月）は月4回のセッション、無制限のAIスマートマッチング、優先予約、パーソナライズされたレコメンデーションが含まれます。どちらのプランもいつでもキャンセルできます。',
    faq_cat3_q4: '隠れた手数料はありますか？',
    faq_cat3_a4: 'ありません。表示された価格がお支払い価格です。すべての価格は該当するVATを含んでいます。初期費用・キャンセル料・隠れた手数料は一切ありません。',
    faq_cat4_q1: '予約済みのセッションをキャンセルできますか？',
    faq_cat4_a1: 'はい。いつでもキャンセルできますが、予定開始時間の1時間前までに行ってください。直前のキャンセル（セッション1時間前以内）はアカウントに記録されます。',
    faq_cat4_q2: 'キャンセルした場合、返金されますか？',
    faq_cat4_a2: 'いいえ。弊社のキャンセルポリシーには、理由を問わず返金は含まれません。1時間以上前にキャンセルした場合、プランによってはセッションクレジットが返还される場合があります。',
    faq_cat5_q1: 'メンターはどのように選ばれますか？',
    faq_cat5_a1: 'GrowVia上のすべてのメンターは手動の承認プロセスを経ています。申請を提出し、チームがバックグラウンド・経験・動機を審査してから承認します。検証済みのメンターのみがプラットフォームに表示されます。',
    faq_cat5_q2: '気に入ったメンターを保存できますか？',
    faq_cat5_a2: 'はい。プロフィールのハートアイコンをクリックしてメンターをお気に入りに追加できます。保存したメンターはダッシュボードの「保存済みメンター」からアクセスでき、直接予約できます。',
    faq_cat5_q3: 'メンターマッチングに満足できない場合はどうすればいいですか？',
    faq_cat5_a3: 'AIマッチングが合わないと感じた場合は、メンター全ディレクトリを閲覧して別のメンターを選ぶことができます。サブスクリプションユーザーは無制限のAIマッチング試行が可能です。',
    faq_cat6_q1: '学校でGrowViaを活用するにはどうすればいいですか？',
    faq_cat6_a1: '学校は機関アカウントを作成し、専用リンクで学生を招待できます。学校のメールアドレスでサインアップした学生は自動的に学校アカウントに連携されます。学校管理者はセッション・参加状況・全体のアクティビティを追跡できます。',
    faq_cat6_q2: '学生は学校を通じてどのようにアクセスしますか？',
    faq_cat6_a2: '学校から学生に招待リンクが送られます。学生は学校のメールアドレスでサインアップし、自動的に貴校のダッシュボードに接続されます。',
    faq_still: 'まだご質問がありますか？',
    faq_still_sub: 'チームがお手伝いします。お気軽にご連絡ください。すぐにご返答します。',
    faq_still_cta: 'お問い合わせ',

