    wwa_mission_p1: '너무 많은 학생과 사회초년생이 같은 도전에 직면합니다. 야망은 있지만 방향이 없습니다.',
    wwa_mission_p2: '동시에 수천 명의 경험 많은 전문가들이 지식을 나누고 다른 사람의 커리어에 실질적인 차이를 만들고 싶어 합니다.',
    wwa_mission_p3: 'GrowVia는 그 간극을 메웁니다. 진정하고 체계적이며 영향력 있는 멘토링 관계를 위한 환경을 만듭니다.',
    wwa_stat_founded: '설립 연도',
    wwa_stat_hq: '본사',
    wwa_stat_langs: '지원 언어',
    wwa_stat_vision: '비전',
    wwa_vision_label: '우리의 비전',
    wwa_vision_title: '질 높은 멘토링의 글로벌 기준이 되기',
    wwa_vision_sub: '우리는 단순한 플랫폼 이상을 만들고 있습니다. 모든 야심찬 사람이 잠재력을 발휘하는 데 필요한 지도에 접근할 수 있는 운동을 만들고 있습니다.',
    wwa_vision_quote: '"GrowVia는 단순한 멘토링이 아닙니다. 당신의 미래에 명확함을 가져다줍니다."',
    wwa_founders_title: '창립자를 만나보세요',
    wwa_founders_sub: '세계가 커리어 지도에 접근하는 방식을 바꾸는 미션을 가진 두 사람.',
    wwa_founder1_bio: '루나는 졸업 후 진로를 선택하는 혼란을 직접 경험했습니다. 자신의 여정을 진정으로 이해하는 멘토를 찾지 못해, 바랐던 플랫폼을 만들기로 결심했습니다.',
    wwa_founder2_bio: '야스민은 인간 중심 디자인과 커뮤니티 구축에 깊은 열정을 가져옵니다. 여러 나라와 산업에서 일하며 글로벌 취업 시장의 복잡성을 이해합니다.',
    wwa_values_title: '우리가 믿는 것',
    wwa_values_sub: 'GrowVia에서 모든 결정을 이끄는 원칙들.',
    wwa_value1_title: '사람 우선',
    wwa_value1_desc: 'GrowVia의 모든 상호작용은 진정한 인간적 연결을 중심으로 만들어집니다. 가장 강력한 지도는 진정으로 관심을 갖는 사람에게서 나온다고 믿습니다.',
    wwa_value2_title: '소음 대신 명확함',
    wwa_value2_desc: '혼란을 제거합니다. 모든 세션은 영감뿐만 아니라 구체적인 다음 단계로 끝납니다.',
    wwa_value3_title: '모두에게 접근 가능',
    wwa_value3_desc: '커리어 지도는 특권이 아니어야 합니다. 어디서나 학생과 전문가에게 양질의 멘토링을 제공하기 위해 노력합니다.',
    wwa_value4_title: '지속적인 성장',
    wwa_value4_desc: '멘토와 멘티 모두 플랫폼의 모든 참가자를 위한 평생 학습을 믿습니다.',
    wwa_cta_title: '이 여정에 함께하세요',
    wwa_cta_sub: '성장을 원하든 나누고 싶든, GrowVia에 자리가 있습니다.',
