    // FAQ page
    faq_badge: '자주 묻는 질문',
    faq_title1: '자주 묻는',
    faq_title2: '질문들',
    faq_sub: 'GrowVia에 대해 알아야 할 모든 것. 답을 찾지 못하셨나요? 직접 문의하세요.',
    faq_cat1: '시작하기',
    faq_cat2: '세션 및 예약',
    faq_cat3: '요금 및 결제',
    faq_cat4: '취소 정책',
    faq_cat5: '멘토',
    faq_cat6: '학교를 위해',
    faq_cat1_q1: 'GrowVia는 어떻게 시작하나요?',
    faq_cat1_a1: '가입하고 프로필을 완성한 후 9.99€에 탐색 세션을 예약하세요. 이 15~20분 입문 세션으로 멘토를 만나고 AI 스마트 매칭 기능을 1회 체험할 수 있습니다. 장기 약속 없음.',
    faq_cat1_q2: '멘토를 검색하려면 계정이 필요한가요?',
    faq_cat1_a2: '전체 멘토 디렉토리에 접근하고 AI 매칭을 사용하려면 프로필을 만들어야 합니다. 프로필 만들기는 무료이며 약 5분이 걸립니다.',
    faq_cat1_q3: '멘티가 되려면 어떻게 하나요?',
    faq_cat1_a3: 'GrowVia에 가입하고 목표와 배경으로 프로필을 완성하면 즉시 멘토를 탐색하고 첫 무료 세션을 예약할 수 있습니다.',
    faq_cat2_q1: '세션은 어떻게 진행되나요?',
    faq_cat2_a1: '세션은 GrowVia 플랫폼에 직접 통합된 Google Meet을 통해 이루어집니다. 세션을 예약하면 고유한 회의 링크가 자동으로 생성되어 이메일로 공유됩니다. 링크를 클릭하면 바로 참여할 수 있습니다.',
    faq_cat2_q2: '세션은 얼마나 오래 진행되나요?',
    faq_cat2_a2: '멘토의 제공 내용과 선호도에 따라 30분 또는 60분 형식으로 이용 가능합니다.',
    faq_cat2_q3: '예정된 세션과 지난 세션을 볼 수 있나요?',
    faq_cat2_a3: '네. 개인 캘린더와 세션 기록은 대시보드에서 확인할 수 있습니다. 예정된 세션, 지난 세션 및 상태(예정, 완료, 취소)를 볼 수 있습니다.',
    faq_cat3_q1: '결제는 어떻게 이루어지나요?',
    faq_cat3_a1: '멘토를 선택하고 시간을 고르면 Stripe 기반의 안전한 결제로 안내됩니다. 탐색 세션은 9.99€(일회성)입니다. 월간 플랜은 매월 갱신되며 언제든지 취소할 수 있습니다.',
    faq_cat3_q2: '결제는 안전한가요?',
    faq_cat3_a2: '물론입니다. 모든 결제는 은행급 TLS 암호화를 사용하는 Stripe를 통해 처리됩니다. GrowVia는 서버에 카드 정보를 저장하지 않습니다. 금융 데이터는 항상 보호됩니다.',
    faq_cat3_q3: '구독 플랜에는 무엇이 포함되나요?',
    faq_cat3_a3: '베이직(19.99€/월)에는 월 2회 세션과 AI 스마트 매칭 1회 사용이 포함됩니다. 프리미엄(39.99€/월)에는 월 4회 세션, 무제한 AI 스마트 매칭, 우선 예약, 개인 맞춤 추천이 포함됩니다. 두 플랜 모두 언제든지 취소할 수 있습니다.',
    faq_cat3_q4: '숨겨진 수수료가 있나요?',
    faq_cat3_a4: '없습니다. 표시된 가격이 지불하는 가격입니다. 모든 가격에는 해당 VAT가 포함됩니다. 설정 비용, 취소 수수료, 숨겨진 요금이 없습니다.',
    faq_cat4_q1: '예약된 세션을 취소할 수 있나요?',
    faq_cat4_a1: '네. 언제든지 취소할 수 있지만 예정된 시작 시간 최소 1시간 전에 취소해야 합니다. 늦은 취소(세션 1시간 이내)는 계정에 기록됩니다.',
    faq_cat4_q2: '취소하면 환불받을 수 있나요?',
    faq_cat4_a2: '아니요. 취소 정책은 취소 이유에 관계없이 환불을 포함하지 않습니다. 1시간 이상 미리 취소하면 플랜에 따라 세션 크레딧이 반환될 수 있습니다.',
    faq_cat5_q1: '멘토는 어떻게 선발되나요?',
    faq_cat5_a1: 'GrowVia의 모든 멘토는 수동 승인 프로세스를 거칩니다. 지원서를 제출하고 팀이 배경, 경험, 동기를 검토한 후 승인합니다. 검증된 멘토만 플랫폼에 나타납니다.',
    faq_cat5_q2: '마음에 드는 멘토를 저장할 수 있나요?',
    faq_cat5_a2: '네. 프로필의 하트 아이콘을 클릭해 멘토를 즐겨찾기에 추가할 수 있습니다. 저장된 멘토는 대시보드의 저장된 멘토에서 접근하고 바로 예약할 수 있습니다.',
    faq_cat5_q3: '멘토 매칭이 맞지 않으면 어떻게 하나요?',
    faq_cat5_a3: 'AI 매칭이 맞지 않으면 전체 멘토 디렉토리를 탐색해 다른 멘토를 선택할 수 있습니다. 구독 사용자는 무제한 AI 매칭 시도를 받습니다.',
    faq_cat6_q1: '학교에서 GrowVia를 어떻게 사용할 수 있나요?',
    faq_cat6_a1: '학교는 기관 계정을 만들고 전용 링크로 학생을 초대할 수 있습니다. 학교 이메일로 가입한 학생은 자동으로 학교 계정에 연결됩니다. 학교 관리자는 세션, 참여, 전체 활동을 추적할 수 있습니다.',
    faq_cat6_q2: '학생들은 학교를 통해 어떻게 접근하나요?',
    faq_cat6_a2: '학교에서 학생들에게 초대 링크를 보냅니다. 학생들은 학교 이메일 주소로 가입하고 자동으로 기관 대시보드에 연결됩니다.',
    faq_still: '아직 질문이 있으신가요?',
    faq_still_sub: '팀이 기꺼이 도와드립니다. 연락주시면 빠르게 답변드리겠습니다.',
    faq_still_cta: '문의하기',

