    // AI Smart Matching page
    ai_badge: '프리미엄 기능',
    ai_title1: 'AI',
    ai_title2: '스마트 매칭',
    ai_sub: '추측은 그만하세요. AI가 목표, 성격, 경험을 분석해 성장을 가장 잘 도울 수 있는 멘토를 호환성 점수와 함께 추천합니다.',
