    // Who We Are page
    wwa_badge: 'Наша история',
    wwa_hero_title1: 'Создано людьми, которые',
    wwa_hero_title2: 'сами были потеряны',
    wwa_hero_sub: 'GrowVia родился из простого разочарования: талантливые и амбициозные люди принимали карьерные решения вслепую. Мы решили это изменить.',
    wwa_mission_label: 'Наша миссия',
    wwa_mission_title: 'Соединять поколения и раскрывать потенциал',
    wwa_mission_p1: 'Слишком многие студенты и молодые специалисты сталкиваются с одной и той же проблемой: у них есть амбиции, но нет направления.',
    wwa_mission_p2: 'В то же время тысячи опытных профессионалов хотят делиться знаниями, передавать опыт и реально влиять на чужую карьеру.',
    wwa_mission_p3: 'GrowVia заполняет этот пробел. Мы создаём условия для подлинных, структурированных и результативных менторских отношений.',
    wwa_stat_founded: 'Год основания',
    wwa_stat_hq: 'Штаб-квартира',
    wwa_stat_langs: 'Поддерживаемые языки',
    wwa_stat_vision: 'Видение',
    wwa_vision_label: 'Наше видение',
    wwa_vision_title: 'Стать мировым эталоном качественного менторства',
    wwa_vision_sub: 'Мы строим не просто платформу. Мы создаём движение, в котором каждый амбициозный человек имеет доступ к руководству, необходимому для полного раскрытия потенциала.',
    wwa_vision_quote: '"GrowVia, это не просто менторство. Это внесение ясности в твоё будущее."',
    wwa_founders_title: 'Познакомься с основателями',
    wwa_founders_sub: 'Два человека с миссией изменить подход мира к карьерному руководству.',
    wwa_founder1_bio: 'Луна на собственном опыте прочувствовала растерянность при выборе карьерного пути. Не найдя менторов, которые по-настоящему понимали её, она создала платформу, о которой мечтала.',
    wwa_founder2_bio: 'Ясмин привносит глубокую страсть к человекоцентричному дизайну и созданию сообществ. Работая в разных странах и отраслях, она понимает сложности глобального рынка труда.',
    wwa_values_title: 'Во что мы верим',
    wwa_values_sub: 'Принципы, которые лежат в основе каждого нашего решения.',
    wwa_value1_title: 'Человек прежде всего',
    wwa_value1_desc: 'Каждое взаимодействие на GrowVia построено вокруг живой человеческой связи. Мы верим, что самое мощное руководство исходит от людей, которым по-настоящему не всё равно.',
    wwa_value2_title: 'Ясность вместо шума',
    wwa_value2_desc: 'Мы прорезаем неразбериху. Каждая сессия завершается конкретными следующими шагами, а не только вдохновением.',
    wwa_value3_title: 'Доступно для всех',
    wwa_value3_desc: 'Карьерное руководство не должно быть привилегией. Мы стараемся сделать качественное менторство доступным для студентов и специалистов везде.',
    wwa_value4_title: 'Непрерывный рост',
    wwa_value4_desc: 'Мы верим в обучение на протяжении всей жизни для всех участников платформы, менторов и подопечных.',
