    // FAQ page
    faq_badge: 'Вопросы и ответы',
    faq_title1: 'Часто задаваемые',
    faq_title2: 'вопросы',
    faq_sub: 'Всё, что нужно знать о GrowVia. Не нашёл ответ? Напиши нам напрямую.',
    faq_cat1: 'Начало работы',
    faq_cat2: 'Сессии и бронирование',
    faq_cat3: 'Оплата и тарифы',
    faq_cat4: 'Политика отмены',
    faq_cat5: 'Менторы',
    faq_cat6: 'Для школ',
    faq_cat1_q1: 'Как начать работу с GrowVia?',
    faq_cat1_a1: 'Зарегистрируйся, заполни профиль и забронируй пробную сессию за 9,99€. Эта 15–20-минутная вводная сессия позволяет познакомиться с ментором и один раз воспользоваться ИИ-подбором. Без долгосрочных обязательств.',
    faq_cat1_q2: 'Нужен ли аккаунт для просмотра менторов?',
    faq_cat1_a2: 'Чтобы получить доступ к полному каталогу менторов и использовать ИИ-подбор, нужно создать профиль. Регистрация бесплатна и занимает около 5 минут.',
    faq_cat1_q3: 'Как стать подопечным?',
    faq_cat1_a3: 'Просто зарегистрируйся на GrowVia, заполни профиль с целями и опытом, и сразу начни просматривать менторов и бронировать первую бесплатную сессию.',
    faq_cat2_q1: 'Как проходят сессии?',
    faq_cat2_a1: 'Сессии проходят через Google Meet, интегрированный напрямую в платформу GrowVia. После бронирования автоматически генерируется уникальная ссылка и отправляется тебе и ментору по email. Просто нажми на ссылку для подключения.',
    faq_cat2_q2: 'Сколько длятся сессии?',
    faq_cat2_a2: 'Сессии доступны в форматах 30 и 60 минут в зависимости от предложений ментора и твоих предпочтений.',
    faq_cat2_q3: 'Можно ли видеть предстоящие и прошедшие сессии?',
    faq_cat2_a3: 'Да. Личный календарь и история сессий доступны в дашборде. Ты видишь предстоящие, прошедшие сессии и их статус (предстоящая, завершённая, отменённая).',
    faq_cat3_q1: 'Как работает оплата?',
    faq_cat3_a1: 'После выбора ментора и времени тебя проводят через безопасную оплату через Stripe. Пробная сессия стоит 9,99€ (единоразово). Ежемесячные планы автоматически продлеваются и могут быть отменены в любое время.',
    faq_cat3_q2: 'Безопасна ли оплата?',
    faq_cat3_a2: 'Абсолютно. Все платежи обрабатываются через Stripe с банковским TLS-шифрованием. GrowVia никогда не хранит данные карты на своих серверах. Твои финансовые данные всегда защищены.',
    faq_cat3_q3: 'Что входит в подписку?',
    faq_cat3_a3: 'Базовый (19,99€/мес) включает 2 сессии в месяц и 1 использование ИИ-подбора. Премиум (39,99€/мес) включает 4 сессии в месяц, неограниченный ИИ-подбор, приоритетное бронирование и персональные рекомендации. Оба тарифа можно отменить в любое время.',
    faq_cat3_q4: 'Есть ли скрытые платежи?',
    faq_cat3_a4: 'Нет. Цена, которую ты видишь, это цена, которую ты платишь. Все цены включают НДС. Никаких вступительных взносов, штрафов за отмену или скрытых платежей.',
    faq_cat4_q1: 'Можно ли отменить забронированную сессию?',
    faq_cat4_a1: 'Да. Ты можешь отменить сессию в любое время, но не позднее чем за 1 час до начала. Поздние отмены (в течение 1 часа до сессии) фиксируются на аккаунте.',
    faq_cat4_q2: 'Вернут ли деньги при отмене?',
    faq_cat4_a2: 'Нет. Наша политика отмены не предусматривает возврат средств независимо от причины. Если отменил более чем за 1 час заранее, кредит сессии может вернуться в зависимости от тарифа.',
    faq_cat5_q1: 'Как отбираются менторы?',
    faq_cat5_a1: 'Каждый ментор на GrowVia проходит ручной процесс одобрения. Они подают заявку, наша команда проверяет опыт, компетенции и мотивацию. Только проверенные менторы появляются на платформе.',
    faq_cat5_q2: 'Можно ли сохранять понравившихся менторов?',
    faq_cat5_a2: 'Да. Добавляй менторов в избранное, нажав на иконку сердца в профиле. Сохранённые менторы доступны в дашборде в разделе «Сохранённые менторы», откуда можно сразу бронировать.',
    faq_cat5_q3: 'Что делать, если подбор ментора не подошёл?',
    faq_cat5_a3: 'Если ИИ-подбор не подходит, просматривай полный каталог менторов и выбирай другого. Пользователи подписки получают неограниченное количество попыток ИИ-подбора.',
    faq_cat6_q1: 'Как моя школа может использовать GrowVia?',
    faq_cat6_a1: 'Школы могут создать институциональный аккаунт и приглашать студентов по специальной ссылке. Студенты, зарегистрировавшиеся с корпоративной почтой, автоматически привязываются к аккаунту школы. Администратор отслеживает сессии, участие и общую активность.',
    faq_cat6_q2: 'Как студенты получают доступ через школу?',
    faq_cat6_a2: 'Школа отправляет студентам ссылку-приглашение. Студенты регистрируются с корпоративной почтой и автоматически подключаются к дашборду учреждения.',
    faq_still: 'Ещё есть вопросы?',
    faq_still_sub: 'Наша команда рада помочь. Напиши нам, и мы быстро ответим.',
    faq_still_cta: 'Связаться',

