    hiw_s2_d2: 'تُعرض نسبة المطابقة لمزيد من الشفافية', hiw_s2_d3: 'احصل على مطابقة غير محدودة باشتراك',
    hiw_s3_title: 'احجز جلسة اكتشاف',
    hiw_s3_desc: 'ابدأ بجلسة اكتشاف، اختر المدة التي تناسبك أنت ومرشدك. التقِ بمرشدك، استكشف التوافق، وجرّب GrowVia قبل الالتزام.',
    hiw_s3_d1: 'مدة الجلسة تُختار عند الحجز',
    hiw_s3_d2: 'رابط الفيديو المتكامل يُولَّد تلقائيًا', hiw_s3_d3: 'الرابط ذاته يُشارَك مع المرشد والمتدرب',
    hiw_s4_title: 'اختر مرشدك', hiw_s4_desc: 'تصفح مجتمعنا المختار من المرشدين الموثقين أو اتبع اقتراح الذكاء الاصطناعي. صفّ حسب الفئة واللغة والتوافر وغيرها.',
    hiw_s4_d1: 'احفظ المرشدين في قائمة المفضلة', hiw_s4_d2: 'اقرأ ملفات المرشدين التفصيلية', hiw_s4_d3: 'شاهد توافر المرشد في الوقت الفعلي',
    hiw_s5_title: 'احجز جلستك', hiw_s5_desc: 'بعد جلسة الاكتشاف، انتقل إلى خطة مدفوعة لجلسات منتظمة ودعم مستمر مع مرشدك.',
    hiw_s5_d1: 'مجاني: ٠€ · جلسة اكتشاف واحدة · ١٥–٢٠ دقيقة',
    hiw_s5_d2: 'أساسي: ٤٫٩٩€/شهر · جلسات قياسية · ٢–٣ مطابقات ذكاء اصطناعي',
    hiw_s5_d3: 'قياسي: ٩٫٩٩€/شهر · الوصول لمعظم المرشدين · مطابقة ذكاء اصطناعي موسّعة',
    hiw_s5_d4: 'مميز: ١٤٫٩٩€/شهر · الوصول لجميع المرشدين · مطابقة ذكاء اصطناعي غير محدودة',
    hiw_s6_title: 'انضم عبر Google Meet', hiw_s6_desc: 'في يوم الجلسة، انضم عبر رابط Google Meet المتكامل. لا تطبيقات إضافية. نقرة واحدة وأنت بداخله.',
    hiw_s6_d1: 'رابط الاجتماع يُولَّد تلقائيًا بعد الحجز', hiw_s6_d2: 'تأكيد بريد إلكتروني مع رابط الانضمام',
    hiw_s6_d3: 'تذكير قبل الجلسة بـ ٢٤ ساعة وساعة واحدة',
    hiw_s7_title: 'واصل نموك', hiw_s7_desc: 'بعد جلسة الاكتشاف، انتقل إلى خطة مدفوعة لجلسات منتظمة ودعم مستمر.',
    hiw_s7_d1: 'أساسي: ٤٫٩٩€/شهر · ٢–٣ جلسات · مطابقات ذكاء اصطناعي',
    hiw_s7_d2: 'قياسي: ٩٫٩٩€/شهر · الوصول لمعظم المرشدين · فلاتر متقدمة',
    hiw_s7_d3: 'مميز: ١٤٫٩٩€/شهر · الوصول لجميع المرشدين · ذكاء اصطناعي غير محدود',
    hiw_s7_d4: 'إلغاء في أي وقت، بلا رسوم خفية',
    hiw_sessions_label: 'مدمج', hiw_sessions_title: 'جلسات تسير بسلاسة.', hiw_sessions_sub: 'كل ما تحتاجه مدمج في المنصة.',
    hiw_c1_title: 'Google Meet مدمج', hiw_c1_desc: 'بعد الحجز، يُولَّد رابط Google Meet فريد تلقائيًا ويُشارَك مع المرشد والمتدرب. نقرة واحدة للانضمام.',
    hiw_c2_title: 'تذكيرات تلقائية', hiw_c2_desc: 'تتلقى تأكيد البريد الإلكتروني فورًا، وتذكيرًا قبل الجلسة بـ ٢٤ ساعة، وآخر قبلها بساعة.',
    hiw_c3_title: 'سياسة الإلغاء', hiw_c3_desc: 'ألغِ قبل ساعة على الأقل من جلستك لتجنب أي مشاكل. الإلغاءات المتأخرة تُسجَّل في ملفك.',
    hiw_notif_label: 'إشعارات', hiw_notif_title1: 'ابقَ على اطلاع في', hiw_notif_title2: 'كل خطوة.',
    hiw_notif_sub: 'نضمن ألا تفوتك جلسة أو تحديث مهم. من الحجز إلى المتابعة، GrowVia تبقيك على اطلاع.',
    hiw_n1: 'تأكيد البريد الإلكتروني بعد الحجز', hiw_n2: 'تذكير قبل جلستك بـ ٢٤ ساعة',
