    // FAQ page
    faq_badge: '常见问题',
    faq_title1: '常见',
    faq_title2: '问题解答',
    faq_sub: '关于 GrowVia 你需要知道的一切。找不到答案？直接联系我们。',
    faq_cat1: '入门指南',
    faq_cat2: '课程与预约',
    faq_cat3: '价格与支付',
    faq_cat4: '取消政策',
    faq_cat5: '导师',
    faq_cat6: '学校合作',
    faq_cat1_q1: '如何在 GrowVia 开始使用？',
    faq_cat1_a1: '注册、完善档案，并以 9.99€ 预约一次探索课程。这次 15–20 分钟的入门课程让你认识导师并免费体验一次 AI 智能匹配功能，无需长期承诺。',
    faq_cat1_q2: '浏览导师需要创建账号吗？',
    faq_cat1_a2: '你需要创建档案才能访问我们完整的导师目录并使用 AI 匹配功能。创建档案免费，约需 5 分钟。',
    faq_cat1_q3: '如何成为学员？',
    faq_cat1_a3: '只需在 GrowVia 注册，填写你的目标和背景完善档案，即可立即开始浏览导师并预约第一次免费课程。',
    faq_cat2_q1: '课程如何进行？',
    faq_cat2_a1: '课程通过 Google Meet 进行，直接集成在 GrowVia 平台中。预约课程后，系统自动生成专属会议链接并通过邮件发送给你和你的导师，点击链接即可加入。',
    faq_cat2_q2: '课程持续多长时间？',
    faq_cat2_a2: '课程提供 30 分钟或 60 分钟两种格式，具体取决于导师的安排和你的偏好。',
    faq_cat2_q3: '可以查看即将进行和过去的课程吗？',
    faq_cat2_a3: '可以。你的个人日历和课程历史记录在仪表板中均可查看，包括即将进行的课程、过往课程及其状态（即将进行、已完成或已取消）。',
    faq_cat3_q1: '如何付款？',
    faq_cat3_a1: '选择导师并确认时间后，你将进入由 Stripe 提供支持的安全结账流程。探索课程费用为 9.99€（一次性）。月度计划按月续费，可随时取消。',
    faq_cat3_q2: '支付安全吗？',
    faq_cat3_a2: '绝对安全。所有支付均通过 Stripe 处理，采用银行级 TLS 加密。GrowVia 绝不在服务器上存储你的银行卡信息，你的财务数据始终受到保护。',
    faq_cat3_q3: '订阅计划包含哪些内容？',
    faq_cat3_a3: 'Basic（19.99€/月）包含每月 2 次课程和 1 次 AI 智能匹配。Premium（39.99€/月）包含每月 4 次课程、无限 AI 智能匹配、优先预约和个性化推荐。两种计划均可随时取消。',
    faq_cat3_q4: '有隐藏费用吗？',
    faq_cat3_a4: '没有。你看到的价格就是你支付的价格。所有价格已含适用税费，无启动费、取消费或隐藏收费。',
    faq_cat4_q1: '可以取消已预约的课程吗？',
    faq_cat4_a1: '可以。你可以随时取消课程，但必须在预定开始时间前至少 1 小时完成取消。延迟取消（在课程前 1 小时内）将记录在你的账号中。',
    faq_cat4_q2: '取消后会退款吗？',
    faq_cat4_a2: '不会。我们的取消政策不包含退款，无论取消原因。如果你在 1 小时前取消，课程积分可能根据你的计划退还。',
    faq_cat5_q1: '导师是如何筛选的？',
    faq_cat5_a1: 'GrowVia 上的每位导师都需经过人工审核流程：提交申请，由我们的团队审核其背景、经验和动机后才能获批。只有经过认证的导师才会显示在平台上。',
    faq_cat5_q2: '可以收藏喜欢的导师吗？',
    faq_cat5_a2: '可以。点击导师档案上的心形图标即可将其加入收藏。已收藏的导师可在仪表板的"已收藏导师"中查看，并可直接从那里预约。',
    faq_cat5_q3: '如果对 AI 匹配的导师不满意怎么办？',
    faq_cat5_a3: '如果 AI 匹配结果不合适，你可以浏览我们的完整导师目录并选择其他导师。订阅用户可享受无限次 AI 匹配。',
    faq_cat6_q1: '学校如何使用 GrowVia？',
    faq_cat6_a1: '学校可以创建机构账号并通过专属链接邀请学生。使用学校邮箱注册的学生将自动关联至学校账号。学校管理员随后可追踪课程、参与情况和整体活动。',
    faq_cat6_q2: '学生如何通过学校获得访问权限？',
    faq_cat6_a2: '学校将向学生发送邀请链接。学生使用学校邮箱注册后，将自动连接至你院校的仪表板。',
    faq_still: '还有其他问题？',
    faq_still_sub: '我们的团队随时乐意提供帮助，联系我们，我们将尽快回复。',
    faq_still_cta: '联系我们',

