    schools_b1_title: 'Gestructureerde Studentenmentoring',
    schools_b1_desc: 'Geef je studenten toegang tot een zorgvuldig samengestelde gemeenschap van ervaren professionals die duidelijke, praktische loopbaanbegeleiding bieden.',
    schools_b2_title: 'Volledig Activiteitsdashboard',
