    schools_b3_title: 'Automatische Studentenkoppeling',
    schools_b3_desc: 'Studenten die zich aanmelden met het schoole-mail worden automatisch gekoppeld aan jouw instelling. Geen handmatige onboarding nodig.',
    schools_b4_title: 'Veilig & Begeleide Omgeving',
