    hiw_sub: 'GrowVia is ontworpen om elke stap eenvoudig, gestructureerd en praktisch te maken. Zo werkt het precies.',
    hiw_s1_title: 'Maak je profiel aan',
    hiw_s1_desc: 'Vertel ons over jezelf: je doelen, achtergrond, loopbaanfase en welke begeleiding je zoekt. Dit duurt ongeveer 5 minuten.',
