    // Who We Are page
    wwa_badge: 'Ons Verhaal',
    wwa_hero_title1: 'Gebouwd door mensen die ook',
    wwa_hero_title2: 'ooit de weg kwijt waren',
    wwa_hero_sub: 'GrowVia ontstond uit een simpele frustratie: getalenteerde, ambitieuze mensen namen loopbaanbeslissingen in het duister. We besloten dat te veranderen.',
    wwa_mission_label: 'Onze Missie',
    wwa_mission_title: 'Generaties verbinden en potentieel ontgrendelen',
    wwa_mission_p1: 'Te veel studenten en jonge professionals staan voor dezelfde uitdaging: ze hebben ambitie, maar missen richting.',
    wwa_mission_p2: 'Tegelijkertijd willen duizenden ervaren professionals iets teruggeven, hun kennis delen en een echte verandering teweegbrengen in iemands carrière.',
    wwa_mission_p3: 'GrowVia overbrugt die kloof. We scheppen de voorwaarden voor oprechte, gestructureerde en impactvolle mentoringrelaties.',
    wwa_stat_founded: 'Opgericht in',
    wwa_stat_hq: 'Hoofdkantoor',
    wwa_stat_langs: 'Ondersteunde Talen',
    wwa_stat_vision: 'Visie',
    wwa_vision_label: 'Onze Visie',
    wwa_vision_title: 'De wereldwijde referentie voor kwaliteitsmentoring worden',
    wwa_vision_sub: 'We bouwen meer dan een platform. We creëren een beweging waarbij elke ambitieuze persoon toegang heeft tot de begeleiding die hij of zij nodig heeft om zijn of haar volledige potentieel te bereiken.',
    wwa_vision_quote: '"GrowVia is meer dan mentoring. Het brengt duidelijkheid in je toekomst."',
    wwa_founders_title: 'Ontmoet de Oprichters',
    wwa_founders_sub: 'Twee mensen met de missie om te veranderen hoe de wereld omgaat met loopbaanbegeleiding.',
    wwa_founder1_bio: 'Luna ervoer zelf de verwarring van het kiezen van een loopbaanpad na haar studie. Niet in staat mentoren te vinden die haar traject werkelijk begrepen, besloot ze het platform te bouwen dat ze had gewenst.',
    wwa_founder2_bio: 'Yasmine heeft een diepe passie voor mensgerichte design en gemeenschapsopbouw. Ze heeft in meerdere landen en sectoren gewerkt en begrijpt de complexiteit van het navigeren op een wereldwijde arbeidsmarkt.',
    wwa_values_title: 'Waar wij in geloven',
    wwa_values_sub: 'De principes die elke beslissing bij GrowVia sturen.',
    wwa_value1_title: 'Mens Voorop',
    wwa_value1_desc: 'Elke interactie op GrowVia is gebouwd rondom echte menselijke verbinding. Wij geloven dat de krachtigste begeleiding komt van mensen die oprecht betrokken zijn.',
    wwa_value2_title: 'Duidelijkheid boven Ruis',
    wwa_value2_desc: 'We snijden door de verwarring heen. Elke sessie eindigt met concrete vervolgstappen, niet alleen inspiratie.',
    wwa_value3_title: 'Toegankelijk voor Iedereen',
    wwa_value3_desc: 'Loopbaanbegeleiding mag geen privilege zijn. We werken eraan om kwaliteitsmentoring beschikbaar te maken voor studenten en professionals overal ter wereld.',
    wwa_value4_title: 'Voortdurende Groei',
    wwa_value4_desc: 'We geloven in levenslang leren voor iedereen op het platform, mentoren en mentees.',
    wwa_cta_title: 'Doe mee aan deze reis',
    wwa_cta_sub: 'Of je nu wilt groeien of iets wilt teruggeven, er is een plek voor jou bij GrowVia.',
    wwa_cta_start: 'Aan de slag',
    wwa_cta_contact: 'Neem contact op',

