    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Veelgestelde',
    faq_title2: 'vragen',
    faq_sub: 'Alles wat je moet weten over GrowVia. Antwoord niet gevonden? Neem dan direct contact met ons op.',
    faq_cat1: 'Aan de slag',
    faq_cat2: 'Sessies & Boekingen',
    faq_cat3: 'Prijzen & Betalingen',
    faq_cat4: 'Annuleringsbeleid',
    faq_cat5: 'Mentoren',
    faq_cat6: 'Voor Scholen',
    faq_cat1_q1: 'Hoe begin ik op GrowVia?',
    faq_cat1_a1: 'Meld je aan, voltooi je profiel en boek een Kennismakingssessie voor €9,99. In deze introductiesessie van 15–20 minuten leer je een mentor kennen en probeer je onze AI Smart Matching eenmalig uit. Geen langetermijnverplichting vereist.',
    faq_cat1_q2: 'Heb ik een account nodig om mentoren te bekijken?',
    faq_cat1_a2: 'Je hebt een profiel nodig om toegang te krijgen tot onze volledige mentordirectory en AI-matching te gebruiken. Een profiel aanmaken is gratis en duurt ongeveer 5 minuten.',
    faq_cat1_q3: 'Hoe word ik mentee?',
    faq_cat1_a3: 'Registreer je op GrowVia, vul je profiel in met je doelen en achtergrond, en je kunt direct beginnen met het verkennen van mentoren en het boeken van je eerste gratis sessie.',
    faq_cat2_q1: 'Hoe werken sessies?',
    faq_cat2_a1: 'Sessies vinden plaats via Google Meet, dat rechtstreeks in het GrowVia-platform is geïntegreerd. Zodra je een sessie boekt, wordt automatisch een unieke meeting-link gegenereerd en via e-mail met jou en je mentor gedeeld. Klik gewoon op de link om deel te nemen.',
    faq_cat2_q2: 'Hoe lang duren de sessies?',
    faq_cat2_a2: 'Sessies zijn beschikbaar in formaten van 30 of 60 minuten, afhankelijk van het aanbod van de mentor en jouw voorkeur.',
    faq_cat2_q3: 'Kan ik mijn komende en voorbije sessies bekijken?',
    faq_cat2_a3: 'Ja. Je persoonlijke kalender en sessiegeschiedenis zijn beschikbaar in je dashboard. Je kunt komende sessies, voorbije sessies en hun status bekijken (aankomend, voltooid of geannuleerd).',
    faq_cat3_q1: 'Hoe werkt de betaling?',
    faq_cat3_a1: 'Nadat je een mentor hebt gekozen en een tijdstip hebt geselecteerd, word je begeleid via een beveiligde checkout aangedreven door Stripe. De Kennismakingssessie kost €9,99 (eenmalig). Maandelijkse plannen worden maandelijks verlengd en kunnen op elk moment worden opgezegd.',
    faq_cat3_q2: 'Is betaling veilig?',
    faq_cat3_a2: 'Absoluut. Alle betalingen worden verwerkt via Stripe, dat gebruik maakt van bankwaardige TLS-versleuteling. GrowVia slaat nooit je kaartinformatie op onze servers op. Je financiële gegevens zijn altijd beschermd.',
    faq_cat3_q3: 'Wat is inbegrepen in de abonnementsplannen?',
    faq_cat3_a3: 'Basic (€4,99/mnd) biedt toegang tot meer mentoren en 2–3 AI-matchings/maand. Standard (€9,99/mnd) biedt toegang tot de meeste mentoren, uitgebreide AI-matching en gepersonaliseerde aanbevelingen. Premium (€14,99/mnd) biedt toegang tot ALLE mentoren, onbeperkte AI-matching en prioriteitsboeking. Alle plannen kunnen op elk moment worden opgezegd.',
    faq_cat3_q4: 'Zijn er verborgen kosten?',
    faq_cat3_a4: 'Nee. De prijs die je ziet is de prijs die je betaalt. Alle prijzen zijn inclusief van toepassing zijnde btw. Er zijn geen installatiekosten, annuleringskosten of verborgen toeslagen.',
    faq_cat4_q1: 'Kan ik een geboekte sessie annuleren?',
    faq_cat4_a1: 'Ja. Je kunt een sessie op elk moment annuleren, maar je moet dit minstens 1 uur voor de geplande starttijd doen. Late annuleringen (binnen 1 uur van de sessie) worden op je account genoteerd.',
    faq_cat4_q2: 'Krijg ik een terugbetaling als ik annuleer?',
    faq_cat4_a2: 'Nee. Ons annuleringsbeleid omvat geen terugbetalingen, ongeacht de reden voor annulering. Als je meer dan 1 uur van tevoren annuleert, kan je sessietegoed worden teruggegeven, afhankelijk van je plan.',
    faq_cat5_q1: 'Hoe worden mentoren geselecteerd?',
    faq_cat5_a1: 'Elke mentor op GrowVia doorloopt een handmatig goedkeuringsproces. Ze dienen een aanmelding in en ons team beoordeelt hun achtergrond, ervaring en motivaties voor goedkeuring. Alleen geverifieerde mentoren verschijnen op het platform.',
    faq_cat5_q2: 'Kan ik mentoren die ik leuk vind opslaan?',
    faq_cat5_a2: 'Ja. Je kunt mentoren aan je favorieten toevoegen door op het hartpictogram op hun profiel te klikken. Je opgeslagen mentoren zijn toegankelijk vanuit je dashboard onder Opgeslagen Mentoren, en je kunt er direct van boeken.',
    faq_cat5_q3: 'Wat als ik niet tevreden ben met mijn mentormatch?',
    faq_cat5_a3: 'Als de AI-match niet goed aanvoelt, kun je onze volledige mentordirectory doorbladeren en een andere mentor kiezen. Abonnementgebruikers krijgen onbeperkte AI-matchingpogingen.',
    faq_cat6_q1: 'Hoe kan mijn school GrowVia gebruiken?',
    faq_cat6_a1: 'Scholen kunnen een institutioneel account aanmaken en studenten uitnodigen via een speciale link. Studenten die zich aanmelden met hun schoole-mail worden automatisch gekoppeld aan het schoolaccount. De schoolbeheerder kan vervolgens sessies, deelname en algemene activiteit bijhouden.',
    faq_cat6_q2: 'Hoe krijgen studenten toegang via hun school?',
    faq_cat6_a2: 'Jouw school stuurt een uitnodigingslink naar studenten. Studenten melden zich aan met hun schoole-mailadres en worden automatisch verbonden met het dashboard van jouw instelling.',
    faq_still: 'Nog vragen?',
    faq_still_sub: 'Ons team helpt je graag. Neem contact op en we reageren snel.',
    faq_still_cta: 'Neem contact op',

