    founders_hero_sub: 'GrowVia łączy ambitnych profesjonalistów z mentorami najwyższej klasy przez AI, w minutach, nie miesiącach.',
    founders_hero_cta: 'Aplikuj do GrowVia',
    founders_reason_label: 'Nasza Racja Bytu',
    founders_reason_title: 'Dwie studentki zarządzania, które szukały mentorów, i postanowiły zbudować to, czego brakowało.',
    founders_reason_sub: 'Bo właściwe połączenie, we właściwym momencie, zmienia wszystko.',
    founders_vision_label: 'Nasza Wizja',
    founders_vision_quote: 'Wierzymy, że łączenie różnych pokoleń tworzy nowy sposób myślenia, w którym mądrość spotyka ambicję, a doświadczenie przyspiesza wzrost.',
    founders_vision_c1_title: 'Rosnij Każdego Dnia',
    founders_vision_c1_desc: 'Angażuj się w ciągły rozwój osobisty i zawodowy. Postęp, nawet mały, to jedyny właściwy kierunek.',
    founders_vision_c2_title: 'Przyjmij Zmiany',
    founders_vision_c2_desc: 'Adaptuj się do wyzwań i aktywnie napędzaj postęp. Najlepsza droga naprzód rzadko jest tą najbardziej oczywistą.',
    founders_vision_c3_title: 'Buduj Zaufanie',
    founders_vision_c3_desc: 'Pielęgnuj uczciwe i przejrzyste relacje, które tworzą realny wpływ. Zaufanie jest fundamentem każdego świetnego połączenia mentoringowego.',
    founders_history_label: 'Nasza Historia',
    founders_history_title: 'Zrodzone z prawdziwej frustracji.',
    founders_history_text: 'GrowVia powstała z prawdziwej frustracji. Luna nie mogła znaleźć mentorów, którzy naprawdę rozumieli jej ścieżkę. Yasmine widziała doświadczonych profesjonalistów bez przestrzeni, aby przekazać to, co wiedzą. Razem postanowiły zbudować platformę, jaką same chciałyby mieć.',
    founders_stories_label: 'Historie',
    founders_stories_title: 'Słowa, które mają znaczenie.',
    founders_video_label: 'Obejrzyj naszą historię',
    founders_partner_title: 'Zostań naszym partnerem.',
    founders_partner_cta: 'Skontaktuj się',
    founders_team_label: 'Zespół',
    founders_team_title: 'Poznaj założycielki.',
    founders_mission_label: 'Nasza Misja',
    founders_mission_title: 'Łączymy pokolenia i odblokowujemy potencjał.',
    founders_mission_p1: 'Zbyt wielu studentów i młodych profesjonalistów stoi przed tym samym wyzwaniem: mają ambicje, ale brakuje im kierunku. Są przytłoczeni wyborami, niepewni swoich mocnych stron i nie mogą znaleźć kogoś, kto naprawdę rozumie ich sytuację.',
    founders_mission_p2: 'Jednocześnie tysiące doświadczonych profesjonalistów chce coś oddać, podzielić się wiedzą i realnie wpłynąć na czyjąś karierę.',
    founders_mission_p3: 'GrowVia wypełnia tę lukę, tworząc warunki do autentycznych, ustrukturyzowanych i wartościowych relacji mentoringowych.',
    founders_stat_founded: 'Rok Założenia',
