    schools_b3_title: 'Automatyczne Powiązanie Studentów',
    schools_b3_desc: 'Studenci rejestrujący się za pomocą szkolnego adresu e-mail są automatycznie powiązani z twoją instytucją. Żadnego ręcznego onboardingu.',
    schools_b4_title: 'Bezpieczne i Nadzorowane',
