    hiw_s3_desc: 'Zacznij od Sesji Odkrywczej, wybierz czas trwania, który najlepiej pasuje tobie i twojemu mentorowi. Poznaj swojego mentora, sprawdź kompatybilność i doświadcz GrowVia przed podjęciem zobowiązania.',
