    wwa_mission_p1: 'Zbyt wielu studentów i młodych profesjonalistów stoi przed tym samym wyzwaniem: mają ambicje, ale brakuje im kierunku.',
    wwa_mission_p2: 'Jednocześnie tysiące doświadczonych profesjonalistów chce coś oddać, podzielić się wiedzą i realnie wpłynąć na czyjąś karierę.',
    wwa_mission_p3: 'GrowVia wypełnia tę lukę. Tworzymy warunki do autentycznych, ustrukturyzowanych i wartościowych relacji mentoringowych.',
    wwa_stat_founded: 'Rok Założenia',
    wwa_stat_hq: 'Siedziba',
    wwa_stat_langs: 'Obsługiwane Języki',
    wwa_stat_vision: 'Wizja',
    wwa_vision_label: 'Nasza Wizja',
    wwa_vision_title: 'Stać się globalnym punktem odniesienia dla jakościowego mentoringu',
    wwa_vision_sub: 'Budujemy coś więcej niż platformę. Tworzymy ruch, w którym każda ambitna osoba ma dostęp do wskazówek potrzebnych do osiągnięcia pełnego potencjału.',
    wwa_vision_quote: '"GrowVia to nie tylko mentoring. To klarowność dla twojej przyszłości."',
    wwa_founders_title: 'Poznaj Założycielki',
    wwa_founders_sub: 'Dwie osoby z misją zmiany sposobu, w jaki świat podchodzi do doradztwa zawodowego.',
    wwa_founder1_bio: 'Luna na własnej skórze doświadczyła zagubienia przy wyborze ścieżki kariery po studiach. Nie mogąc znaleźć mentorów, którzy naprawdę rozumieli jej drogę, postanowiła zbudować platformę, jakiej sama pragnęła.',
    wwa_founder2_bio: 'Yasmine wnosi głęboką pasję do projektowania skoncentrowanego na człowieku i budowania społeczności. Pracując w wielu krajach i branżach, rozumie złożoność poruszania się po globalnym rynku pracy.',
    wwa_values_title: 'W co wierzymy',
    wwa_values_sub: 'Zasady, które kierują każdą decyzją podejmowaną w GrowVia.',
    wwa_value1_title: 'Człowiek Przede Wszystkim',
    wwa_value1_desc: 'Każda interakcja na GrowVia jest zbudowana wokół prawdziwego ludzkiego połączenia. Wierzymy, że najbardziej wartościowe wskazówki pochodzą od ludzi, którym naprawdę zależy.',
    wwa_value2_title: 'Jasność ponad Szum',
    wwa_value2_desc: 'Przecinamy przez zamieszanie. Każda sesja kończy się konkretnymi następnymi krokami, a nie tylko inspiracją.',
    wwa_value3_title: 'Dostępne dla Wszystkich',
    wwa_value3_desc: 'Doradztwo zawodowe nie powinno być przywilejem. Pracujemy nad tym, aby mentoring wysokiej jakości był dostępny dla studentów i profesjonalistów wszędzie.',
    wwa_value4_title: 'Ciągły Rozwój',
    wwa_value4_desc: 'Wierzymy w uczenie się przez całe życie dla wszystkich na platformie, mentorów i mentees.',
    wwa_cta_title: 'Dołącz do nas w tej podróży',
    wwa_cta_sub: 'Czy chcesz się rozwijać, czy chcesz coś dać innym, jest dla ciebie miejsce w GrowVia.',
    wwa_cta_start: 'Zacznij',
    wwa_cta_contact: 'Skontaktuj się',

