    // FAQ page
    faq_badge: 'FAQ',
    faq_title1: 'Najczęściej zadawane',
    faq_title2: 'pytania',
    faq_sub: 'Wszystko, co musisz wiedzieć o GrowVia. Nie znalazłeś odpowiedzi? Skontaktuj się z nami bezpośrednio.',
    faq_cat1: 'Pierwsze Kroki',
    faq_cat2: 'Sesje i Rezerwacje',
    faq_cat3: 'Cennik i Płatności',
    faq_cat4: 'Polityka Anulowania',
    faq_cat5: 'Mentorzy',
    faq_cat6: 'Dla Szkół',
    faq_cat1_q1: 'Jak zacząć korzystać z GrowVia?',
    faq_cat1_a1: 'Zarejestruj się, uzupełnij profil i zarezerwuj Sesję Odkrywczą za €9,99. Ta 15–20 minutowa sesja wstępna pozwala poznać mentora i raz wypróbować funkcję AI Smart Matching. Żadnych długoterminowych zobowiązań.',
    faq_cat1_q2: 'Czy potrzebuję konta, aby przeglądać mentorów?',
    faq_cat1_a2: 'Musisz utworzyć profil, aby uzyskać dostęp do naszego pełnego katalogu mentorów i korzystać z dopasowania AI. Tworzenie profilu jest bezpłatne i trwa około 5 minut.',
    faq_cat1_q3: 'Jak zostać mentee?',
    faq_cat1_a3: 'Po prostu zarejestruj się na GrowVia, uzupełnij profil swoimi celami i tłem, i możesz od razu zacząć przeglądać mentorów i zarezerwować pierwszą bezpłatną sesję.',
    faq_cat2_q1: 'Jak działają sesje?',
    faq_cat2_a1: 'Sesje odbywają się przez Google Meet, który jest zintegrowany bezpośrednio z platformą GrowVia. Po zarezerwowaniu sesji automatycznie generowany jest unikalny link do spotkania i udostępniany zarówno tobie, jak i twojemu mentorowi przez e-mail. Wystarczy kliknąć link, aby dołączyć.',
    faq_cat2_q2: 'Jak długo trwają sesje?',
    faq_cat2_a2: 'Sesje są dostępne w formatach 30 lub 60 minut, w zależności od oferty mentora i twoich preferencji.',
    faq_cat2_q3: 'Czy mogę zobaczyć nadchodzące i poprzednie sesje?',
    faq_cat2_a3: 'Tak. Twój osobisty kalendarz i historia sesji są dostępne w panelu. Możesz zobaczyć nadchodzące sesje, poprzednie sesje i ich status (nadchodząca, ukończona lub anulowana).',
    faq_cat3_q1: 'Jak działa płatność?',
    faq_cat3_a1: 'Po wybraniu mentora i wybraniu terminu przechodzisz przez bezpieczny checkout obsługiwany przez Stripe. Sesja Odkrywcza kosztuje €9,99 (jednorazowo). Plany miesięczne odnawiane są co miesiąc i można je anulować w dowolnym momencie.',
    faq_cat3_q2: 'Czy płatność jest bezpieczna?',
    faq_cat3_a2: 'Absolutnie. Wszystkie płatności są przetwarzane przez Stripe, który używa szyfrowania TLS klasy bankowej. GrowVia nigdy nie przechowuje danych karty na naszych serwerach. Twoje dane finansowe są zawsze chronione.',
    faq_cat3_q3: 'Co jest zawarte w planach subskrypcji?',
    faq_cat3_a3: 'Basic (€4,99/mies.) obejmuje dostęp do więcej mentorów i 2–3 dopasowania AI/miesiąc. Standard (€9,99/mies.) obejmuje dostęp do większości mentorów, rozszerzone dopasowanie AI i spersonalizowane rekomendacje. Premium (€14,99/mies.) obejmuje dostęp do WSZYSTKICH mentorów, nieograniczone dopasowanie AI i priorytetową rezerwację. Wszystkie plany można anulować w dowolnym momencie.',
    faq_cat3_q4: 'Czy są jakieś ukryte opłaty?',
    faq_cat3_a4: 'Nie. Cena, którą widzisz, to cena, którą płacisz. Wszystkie ceny zawierają odpowiedni podatek VAT. Nie ma opłat konfiguracyjnych, opłat za anulowanie ani ukrytych opłat.',
    faq_cat4_q1: 'Czy mogę anulować zarezerwowaną sesję?',
    faq_cat4_a1: 'Tak. Możesz anulować sesję w dowolnym momencie, ale musisz to zrobić co najmniej 1 godzinę przed planowanym czasem rozpoczęcia. Późne anulowania (w ciągu 1 godziny od sesji) są odnotowywane na twoim koncie.',
    faq_cat4_q2: 'Czy otrzymam zwrot, jeśli anuluję?',
    faq_cat4_a2: 'Nie. Nasza polityka anulowania nie obejmuje zwrotów, niezależnie od powodu anulowania. Jeśli anulujesz z więcej niż 1 godziną wyprzedzenia, twój kredyt sesji może zostać zwrócony w zależności od twojego planu.',
    faq_cat5_q1: 'Jak są wybierani mentorzy?',
    faq_cat5_a1: 'Każdy mentor na GrowVia przechodzi przez ręczny proces zatwierdzania. Składają wniosek, a nasz zespół sprawdza ich tło, doświadczenie i motywacje przed zatwierdzeniem. Tylko zweryfikowani mentorzy pojawiają się na platformie.',
    faq_cat5_q2: 'Czy mogę zapisać mentorów, których lubię?',
    faq_cat5_a2: 'Tak. Możesz dodawać mentorów do ulubionych, klikając ikonę serca na ich profilu. Twoi zapisani mentorzy są dostępni z panelu w sekcji Zapisani Mentorzy i możesz rezerwować bezpośrednio stamtąd.',
    faq_cat5_q3: 'Co, jeśli nie jestem zadowolony z dopasowania mentora?',
    faq_cat5_a3: 'Jeśli dopasowanie AI nie wydaje się właściwe, możesz przeglądać nasz pełny katalog mentorów i wybrać innego mentora. Użytkownicy z subskrypcją mają nieograniczone próby dopasowania AI.',
    faq_cat6_q1: 'Jak moja szkoła może korzystać z GrowVia?',
    faq_cat6_a1: 'Szkoły mogą tworzyć konto instytucjonalne i zapraszać studentów przez dedykowany link. Studenci rejestrujący się przy użyciu szkolnego adresu e-mail są automatycznie powiązani z kontem szkolnym. Administrator szkoły może następnie śledzić sesje, uczestnictwo i ogólną aktywność.',
    faq_cat6_q2: 'Jak studenci uzyskują dostęp przez swoją szkołę?',
    faq_cat6_a2: 'Twoja szkoła wyśle studentom link zaproszeniowy. Studenci rejestrują się przy użyciu szkolnego adresu e-mail i są automatycznie połączeni z dashboardem twojej instytucji.',
    faq_still: 'Nadal masz pytania?',
    faq_still_sub: 'Nasz zespół chętnie pomoże. Skontaktuj się, a odpowiemy szybko.',
    faq_still_cta: 'Skontaktuj się',

