    // Mentor Certification page
    cert_badge: 'Certyfikacja Mentora',
    cert_title1: 'Zostań Certyfikowanym',
    cert_title2: 'Mentorem GrowVia',
    cert_sub: 'Wszyscy mentorzy na GrowVia przechodzą krótką certyfikację przed aktywacją. Zajmuje mniej niż godzinę i robi całą różnicę.',
    cert_process_label: 'Proces',
    cert_process_title: 'Trzy kroki do certyfikacji',
    cert_process_sub: 'Mniej niż godzina. Wykonane raz. Ważne na stałe.',
    cert_s1_title: 'Obejrzyj 3 krótkie filmy szkoleniowe',
    cert_s1_desc: 'Poznaj sprawdzone techniki skutecznego mentoringu, aktywnego słuchania, ustalania celów i udzielania informacji zwrotnej, która naprawdę trafia.',
    cert_s2_title: 'Ukończ krótką ocenę',
    cert_s2_desc: 'Krótki quiz, aby potwierdzić twoje zrozumienie i upewnić się, że jesteś gotowy prowadzić mentees z pewnością.',
    cert_s3_title: 'Zdobądź swoją certyfikowaną odznakę',
    cert_s3_desc: 'Twój publiczny profil wyświetla odznakę "GrowVia Certyfikowany Mentor", natychmiast widoczną dla mentees przeglądających platformę.',
    cert_step: 'Krok',
    cert_impact_label: 'Wpływ',
    cert_impact_title: 'Dlaczego to ma znaczenie',
    cert_impact_sub: 'Certyfikacja buduje zaufanie po obu stronach relacji.',
    cert_mentees_label: 'Dla mentees',
    cert_mentees_title: 'Każdy mentor został zweryfikowany i przeszkolony.',
    cert_mentees_desc: 'Wiesz, że każdy mentor, którego spotykasz, został zweryfikowany i przeszkolony. Żadnych domysłów. Kiedy rezerwujesz sesję z GrowVia Certyfikowanym Mentorem, pracujesz z kimś, kto wie, jak prowadzić, słuchać i pomóc ci iść naprzód.',
