    wwa_hero_sub: "GrowVia basit bir hayal kırıklığından doğdu: yetenekli ve hırslı insanlar kariyer kararlarını karanlıkta alıyordu. Bunu değiştirmeye karar verdik.",
    wwa_mission_label: 'Misyonumuz',
