    wwa_vision_title: 'Kaliteli mentorluğun küresel referansı olmak',
    wwa_vision_sub: 'Sadece bir platform değil, bir hareket inşa ediyoruz. Her hırslı bireyin tam potansiyeline ulaşmak için ihtiyaç duyduğu rehberliğe erişebildiği bir dünya.',
    wwa_vision_quote: '"GrowVia sadece mentorluk değil. Geleceğine netlik getiriyor."',
    wwa_founders_title: 'Kurucularla Tanışın',
    wwa_founders_sub: 'Dünyanın kariyer rehberliğine yaklaşımını değiştirme misyonundaki iki kişi.',
    wwa_founder1_bio: 'Luna, mezuniyetinin ardından kariyer yolu seçimindeki kargaşayı bizzat yaşadı. Kendi yolculuğunu gerçekten anlayan mentorlar bulamayınca, keşke sahip olsaydı diye düşündüğü platformu inşa etmeye karar verdi.',
    wwa_founder2_bio: 'Yasmine, insan odaklı tasarım ve topluluk oluşturmaya derin bir tutku besliyor. Birden fazla ülke ve sektörde çalışmış biri olarak, küresel iş piyasasında yol bulmanın karmaşıklığını iyi biliyor.',
