    wwa_value1_desc: "GrowVia'daki her etkileşim gerçek insan bağlantısı etrafında kurulmuştur. En güçlü rehberliğin gerçekten önem veren insanlardan geldiğine inanıyoruz.",
    wwa_value2_title: 'Gürültü Değil Netlik',
    wwa_value2_desc: 'Kargaşayı aradan çıkarıyoruz. Her oturum yalnızca ilham vermekle kalmaz, somut sonraki adımlarla sona erer.',
