    wwa_value3_desc: 'Kariyer rehberliği bir ayrıcalık olmamalı. Kaliteli mentorluğu her yerdeki öğrenci ve profesyoneller için erişilebilir kılmak için çalışıyoruz.',
    wwa_value4_title: 'Sürekli Büyüme',
