    // FAQ page
    faq_badge: 'SSS',
    faq_title1: 'Sıkça sorulan',
    faq_title2: 'sorular',
    faq_sub: 'GrowVia hakkında bilmen gereken her şey. Cevabını bulamıyor musun? Bize doğrudan ulaş.',
    faq_cat1: 'Başlarken',
    faq_cat2: 'Oturumlar & Rezervasyon',
    faq_cat3: 'Fiyat & Ödeme',
    faq_cat4: 'İptal Politikası',
    faq_cat5: 'Mentorlar',
    faq_cat6: 'Okullar İçin',
    faq_cat1_q1: 'GrowVia\'ya nasıl başlarım?',
    faq_cat1_a1: 'Kayıt ol, profilini tamamla ve 9,99€ karşılığında bir Keşif Oturumu rezerve et. Bu 15–20 dakikalık tanışma oturumu bir mentorla tanışmanı ve YZ Akıllı Eşleştirme özelliğimizi bir kez deneyimlemeni sağlar. Uzun vadeli taahhüt gerekmez.',
    faq_cat1_q2: 'Mentor listesine göz atmak için hesap açmam gerekiyor mu?',
    faq_cat1_a2: 'Tam mentor dizinimize erişmek ve YZ eşleştirmeyi kullanmak için profil oluşturman gerekiyor. Profil oluşturmak ücretsizdir ve yaklaşık 5 dakika sürer.',
    faq_cat1_q3: 'Menter nasıl olurum?',
    faq_cat1_a3: 'GrowVia\'ya kayıt ol, hedeflerin ve geçmişinle profilini tamamla, ardından hemen mentor listesine göz atabilir ve ilk ücretsiz oturumunu rezerve edebilirsin.',
    faq_cat2_q1: 'Oturumlar nasıl işliyor?',
    faq_cat2_a1: 'Oturumlar, doğrudan GrowVia platformuna entegre edilmiş Google Meet üzerinden gerçekleşiyor. Oturumu rezerve ettiğinde benzersiz bir toplantı bağlantısı otomatik olarak oluşturulur ve hem sana hem de mentoruna e-posta ile gönderilir. Bağlantıya tıklamanız yeterli.',
    faq_cat2_q2: 'Oturumlar ne kadar sürer?',
    faq_cat2_a2: 'Oturumlar, mentorun teklifleri ve tercihine göre 30 veya 60 dakikalık formatlarda sunulur.',
    faq_cat2_q3: 'Yaklaşan ve geçmiş oturumlarımı görebilir miyim?',
    faq_cat2_a3: 'Evet. Kişisel takvimine ve oturum geçmişine panondan erişebilirsin. Yaklaşan oturumları, geçmiş oturumları ve durumlarını (yaklaşan, tamamlanan veya iptal edilen) görebilirsin.',
    faq_cat3_q1: 'Ödeme nasıl işliyor?',
    faq_cat3_a1: "Mentor seçip bir zaman dilimi belirledikten sonra Stripe tarafından güçlendirilen güvenli bir ödeme sürecine yönlendirilirsin. Keşif Oturumu 9,99€'dur (tek seferlik). Aylık planlar aylık yenilenir ve istediğin zaman iptal edilebilir.",
    faq_cat3_q2: 'Ödeme güvenli mi?',
    faq_cat3_a2: 'Kesinlikle. Tüm ödemeler banka düzeyinde TLS şifrelemesi kullanan Stripe üzerinden işlenir. GrowVia kart bilgilerini sunucularımızda hiçbir zaman saklamaz. Finansal verileriniz her zaman korunur.',
    faq_cat3_q3: 'Abonelik planlarına neler dahil?',
    faq_cat3_a3: 'Temel (19,99€/ay) ayda 2 oturum ve 1 YZ Akıllı Eşleştirme kullanımını içerir. Premium (39,99€/ay) ayda 4 oturum, sınırsız YZ Akıllı Eşleştirme, öncelikli rezervasyon ve kişiselleştirilmiş öneriler içerir. Her iki plan da istediğin zaman iptal edilebilir.',
    faq_cat3_q4: 'Gizli ücret var mı?',
    faq_cat3_a4: 'Hayır. Gördüğün fiyat, ödediğin fiyattır. Tüm fiyatlar uygulanabilir KDV dahildir. Kurulum ücreti, iptal ücreti veya gizli ücret yoktur.',
    faq_cat4_q1: 'Rezerve ettiğim bir oturumu iptal edebilir miyim?',
    faq_cat4_a1: 'Evet. Oturumu istediğin zaman iptal edebilirsin; ancak bunu planlanan başlangıç saatinden en az 1 saat önce yapman gerekir. Geç iptal işlemleri (oturumdan 1 saat içinde) hesabına kaydedilir.',
    faq_cat4_q2: 'İptal edersem para iadesi alır mıyım?',
    faq_cat4_a2: 'Hayır. İptal politikamız iptal nedeninden bağımsız olarak para iadesi öngörmez. 1 saatten önce iptal edersen, planına bağlı olarak oturum kredin iade edilebilir.',
    faq_cat5_q1: 'Mentorlar nasıl seçiliyor?',
    faq_cat5_a1: "GrowVia'daki her mentor manuel onay sürecinden geçiyor. Başvurularını yapıyorlar ve ekibimiz onaylamadan önce geçmişlerini, deneyimlerini ve motivasyonlarını inceliyor. Yalnızca doğrulanmış mentorlar platformda yer alıyor.",
    faq_cat5_q2: 'Beğendiğim mentorları kaydedebilir miyim?',
    faq_cat5_a2: 'Evet. Mentorların profilindeki kalp simgesine tıklayarak favorilerine ekleyebilirsin. Kaydedilen mentorlarına panondan Kayıtlı Mentorlar bölümü altında erişebilir ve doğrudan oradan rezervasyon yapabilirsin.',
    faq_cat5_q3: 'Mentor eşleşmemden memnun olmazsam ne yapabilirim?',
    faq_cat5_a3: 'YZ eşleşmesi doğru gelmiyorsa tam mentor dizinimize göz atabilir ve farklı bir mentor seçebilirsin. Abonelik kullanıcıları sınırsız YZ eşleştirme denemesi hakkına sahiptir.',
    faq_cat6_q1: 'Okulumuz GrowVia\'yı nasıl kullanabilir?',
    faq_cat6_a1: 'Okullar bir kurumsal hesap oluşturabilir ve öğrencileri özel bir bağlantı aracılığıyla davet edebilir. Okul e-postasını kullanarak kayıt olan öğrenciler okul hesabına otomatik olarak bağlanır. Okul yöneticisi ardından oturumları, katılımı ve genel etkinliği takip edebilir.',
    faq_cat6_q2: 'Öğrenciler okulları aracılığıyla nasıl erişim sağlıyor?',
    faq_cat6_a2: 'Okulunuz öğrencilere bir davet bağlantısı gönderecek. Öğrenciler okul e-posta adresleriyle kayıt olur ve kurumunuzun panosuna otomatik olarak bağlanır.',
    faq_still: 'Hâlâ soruların mı var?',
    faq_still_sub: 'Ekibimiz yardım etmekten mutluluk duyar. Ulaş, en kısa sürede geri döneceğiz.',
    faq_still_cta: 'Bize Ulaş',

